export default JSON.parse("{\"workId\":\"cai-gen-tan\",\"chapter\":{\"id\":\"cai-gen-tan_ch-3\",\"workId\":\"cai-gen-tan\",\"order\":3,\"title\":\"評議\",\"difficulty\":3,\"estimatedMinutes\":54,\"passageIds\":[\"cai-gen-tan_ch-3_p-1\",\"cai-gen-tan_ch-3_p-2\",\"cai-gen-tan_ch-3_p-3\",\"cai-gen-tan_ch-3_p-4\",\"cai-gen-tan_ch-3_p-5\",\"cai-gen-tan_ch-3_p-6\",\"cai-gen-tan_ch-3_p-7\",\"cai-gen-tan_ch-3_p-8\",\"cai-gen-tan_ch-3_p-9\",\"cai-gen-tan_ch-3_p-10\",\"cai-gen-tan_ch-3_p-11\",\"cai-gen-tan_ch-3_p-12\",\"cai-gen-tan_ch-3_p-13\",\"cai-gen-tan_ch-3_p-14\",\"cai-gen-tan_ch-3_p-15\",\"cai-gen-tan_ch-3_p-16\",\"cai-gen-tan_ch-3_p-17\",\"cai-gen-tan_ch-3_p-18\",\"cai-gen-tan_ch-3_p-19\",\"cai-gen-tan_ch-3_p-20\",\"cai-gen-tan_ch-3_p-21\",\"cai-gen-tan_ch-3_p-22\",\"cai-gen-tan_ch-3_p-23\",\"cai-gen-tan_ch-3_p-24\",\"cai-gen-tan_ch-3_p-25\",\"cai-gen-tan_ch-3_p-26\",\"cai-gen-tan_ch-3_p-27\",\"cai-gen-tan_ch-3_p-28\",\"cai-gen-tan_ch-3_p-29\",\"cai-gen-tan_ch-3_p-30\",\"cai-gen-tan_ch-3_p-31\",\"cai-gen-tan_ch-3_p-32\",\"cai-gen-tan_ch-3_p-33\",\"cai-gen-tan_ch-3_p-34\",\"cai-gen-tan_ch-3_p-35\",\"cai-gen-tan_ch-3_p-36\",\"cai-gen-tan_ch-3_p-37\",\"cai-gen-tan_ch-3_p-38\",\"cai-gen-tan_ch-3_p-39\",\"cai-gen-tan_ch-3_p-40\",\"cai-gen-tan_ch-3_p-41\",\"cai-gen-tan_ch-3_p-42\",\"cai-gen-tan_ch-3_p-43\",\"cai-gen-tan_ch-3_p-44\",\"cai-gen-tan_ch-3_p-45\",\"cai-gen-tan_ch-3_p-46\",\"cai-gen-tan_ch-3_p-47\",\"cai-gen-tan_ch-3_p-48\",\"cai-gen-tan_ch-3_p-49\",\"cai-gen-tan_ch-3_p-50\",\"cai-gen-tan_ch-3_p-51\",\"cai-gen-tan_ch-3_p-52\",\"cai-gen-tan_ch-3_p-53\",\"cai-gen-tan_ch-3_p-54\",\"cai-gen-tan_ch-3_p-55\",\"cai-gen-tan_ch-3_p-56\",\"cai-gen-tan_ch-3_p-57\",\"cai-gen-tan_ch-3_p-58\",\"cai-gen-tan_ch-3_p-59\",\"cai-gen-tan_ch-3_p-60\",\"cai-gen-tan_ch-3_p-61\",\"cai-gen-tan_ch-3_p-62\",\"cai-gen-tan_ch-3_p-63\",\"cai-gen-tan_ch-3_p-64\",\"cai-gen-tan_ch-3_p-65\",\"cai-gen-tan_ch-3_p-66\",\"cai-gen-tan_ch-3_p-67\",\"cai-gen-tan_ch-3_p-68\",\"cai-gen-tan_ch-3_p-69\",\"cai-gen-tan_ch-3_p-70\",\"cai-gen-tan_ch-3_p-71\",\"cai-gen-tan_ch-3_p-72\",\"cai-gen-tan_ch-3_p-73\"],\"tags\":[\"文學\",\"處世\",\"評議\"]},\"passages\":[{\"id\":\"cai-gen-tan_ch-3_p-1\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":1,\"canonicalText\":\"兩個空拳握古今，握住了還當放手；一條竹杖挑風月，挑到時也要息肩。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-1_s-1\",\"cai-gen-tan_ch-3_p-1_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"憑著兩隻空空的拳頭彷彿想掌握古往今來的一切，但即使真的握住了，最終也應當主動放手；挑著一根竹杖想要擔盡人間的美好風月，但即使挑到了，到了合適的時候也要卸下重擔、停步歇息。\",\"analysis\":\"【主題與背景】此段以極具禪意與詩意的象徵手法，探討了「執著」與「放下」的關係。「空拳握古今」象徵人類無窮的權力欲與征服欲，歷史上的帝王將相雖建不世之功，終歸黃土，故曰「還當放手」。\\\\n【詞義與名物】「竹杖挑風月」則是文人隱士對審美與清雅生活的追求，但作者警示，即便是高雅的「風月」，若過度執著、將其視為心靈的負擔，同樣會成為另一種執念，因此也需要「息肩」（卸下負擔）。\\\\n【思想與篇章】這體現了禪宗徹底的無住、無執智慧。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-2\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":2,\"canonicalText\":\"堦下幾點飛翠落紅，收拾了無非詩料；窻前一片浮青映白，悟入處盡是禪機。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-2_s-1\",\"cai-gen-tan_ch-3_p-2_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"臺階下飄落的幾點翠綠葉片與殷紅花瓣，收拾起來無一不是寫詩的好素材；窗前那一片隨風浮動的青翠綠意與倒映的明亮白光，在用心感悟的當下，全都是參透生命本源的禪意玄機。\",\"analysis\":\"【主題與背景】此段描繪了日常生活中的詩意與禪機，體現了宋明理學「萬物靜觀皆自得」與禪宗「青青翠竹盡是法身，鬱鬱黃花無非般若」的境界。臺階下的落花落葉（飛翠落紅）與窗外的山色日光（浮青映白），在浮躁者眼中只是尋常雜物，但在心靈澄淨的隱士眼中，卻是詩歌的靈感與佛性的顯現。\\\\n【詞義與名物】說明只要心靈覺醒，當下即是道場，自然萬物皆在說法。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-3\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":3,\"canonicalText\":\"忽覩天際彩雲，常疑好事皆虛事；再觀山中閒木，方信閒人是福人。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-3_s-1\",\"cai-gen-tan_ch-3_p-3_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"偶然看見天邊絢麗的彩雲轉瞬即逝，就常常會懷疑世間那些美好的事物，最終都只是一場虛幻；再次觀察山林裡那些不中用而得以保全天年的閒散樹木，才真正相信能擺脫世俗紛擾的閒散之人，才是真正有福氣的人。\",\"analysis\":\"【訓詁與名物】\\\\n「覩」同睹，看見；「彩雲」比喻世間美好但短暫易逝的事物，如功名富貴；「閒木」指不具備實用價值，不會被工匠砍伐而能自然生長於山林中的樹木，語出《莊子》的「無用之木」；「閒人」指遠離官場爭鬥、心境清閒自在的人。\\\\n【章法與結構】\\\\n全句為一對偶句，上聯由「天際彩雲」的易散，聯想到「好事皆虛事」，抒發對榮華富貴無常的感嘆；下聯從「山中閒木」的長存，領悟到「閒人是福人」的真諦。由天上景寫到山中物，由虛無縹緲的彩雲對比穩固常在的閒木，一「疑」一「信」，情感層層推進，理趣盎然。\\\\n【思想與義理】\\\\n此段文字深受莊子「無用之用」哲學的啟發。世俗之人多追求功名利祿等「好事」，卻不知這些如同天際彩雲般虛幻無常，一旦失去便生痛苦。相反，山中的「閒木」因為對世俗「無用」，反而免於被砍伐的命運，得以保全天年。作者藉此點出，人若能放下對名利的執著，做一個不受羈絆的「閒人」，才是保全性命、獲得心靈真正自由與幸福的最佳途徑。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-4\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":4,\"canonicalText\":\"東海水曾聞無定波，世事何須扼腕？北邙山未曾留閒地，人生且自舒眉。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-4_s-1\",\"cai-gen-tan_ch-3_p-4_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"早就聽說過東海的水從來沒有平息過波浪，世間事物的變化也是如此，我們又何必為此感到惋惜悲憤呢？北邙山上到處都是墳墓，未曾留下一塊空閒的土地，人生終究難逃一死，倒不如暫且放寬心胸，眉頭舒展地過日子吧。\",\"analysis\":\"【訓詁與名物】\\\\n「東海」泛指大海；「無定波」指波浪翻滾，從不停息，比喻世事變幻無常；「扼腕」指用手握住手腕，形容情緒激動、憤慨或惋惜；「北邙山」位於河南洛陽北，古代多為王侯將相與達官貴人的墓地，後泛指墓地或死亡的歸宿；「舒眉」意為舒展眉頭，形容心情舒暢、不再愁苦。\\\\n【章法與結構】\\\\n這是一副對仗工整的聯語。「東海水」對「北邙山」，「無定波」對「留閒地」，「世事何須」對「人生且自」，「扼腕」對「舒眉」。上聯從空間的浩瀚與動態（大海無定波）切入，點出世事的無常；下聯從生命的終點與靜態（北邙山無閒地）著眼，指出死亡的必然。兩相映照，氣勢豁達。\\\\n【思想與義理】\\\\n此段充滿了曠達的人生觀與生死觀。作者以東海波濤的不息來隱喻世俗社會的動盪與變化，告訴人們既然無常是常態，就不必為了得失而憤怒惋惜；再以北邙山擠滿墳墓來提醒眾生，無論生前如何顯赫，最終都將歸於一抔黃土。既然生死與無常皆無法改變，智者便應該學會放下執念，豁達面對，把握當下的平靜與喜悅，達到「舒眉」的自在境界。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-5\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":5,\"canonicalText\":\"天地尚無停息，日月且有盈虧，況區區人世能事事圓滿而時時暇逸乎？只是向忙裏偷閒，遇缺處知足，則操縱在我，作息自如，即造物不得與之論勞逸較虧盈矣！\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-5_s-1\",\"cai-gen-tan_ch-3_p-5_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"天地運作尚且運轉不息，太陽月亮也都有圓缺盈虧，更何況這渺小的人世間，又怎能要求事事都十全十美、時時都悠閒安逸呢？只要懂得在忙碌的生活中偷得片刻清閒，在不完美與欠缺的境遇中保持知足常樂，那麼生命的主動權就掌握在自己手中，勞作與休息都能自如應對，連創造萬物的大自然也無法與你爭論勞累安逸，或計較盈虧得失了！\",\"analysis\":\"【主題與背景】本段是一篇極具實用價值的涉世心靈指南。作者首先指出「不完美」與「變動」是宇宙的客觀規律（日月盈虧、天地無停），世人若追求絕對的圓滿與永久的安逸，只是自尋煩惱。\\\\n【詞義與名物】解決之道在於「忙裏偷閒」與「遇缺處知足」，這是一種主體性的確立。\\\\n【思想與篇章】當人能夠在心靈上自我調節，不受外在客觀環境的奴役，就能達到「操縱在我」的自由境界，連命運（造物）也無可奈何。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-6\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":6,\"canonicalText\":\"「霜天聞鶴唳，雪夜聽雞鳴，」得乾坤清純之氣。「晴空看鳥飛，活水觀魚戲，」識宇宙活潑之機。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-6_s-1\",\"cai-gen-tan_ch-3_p-6_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"耳中常聽到不順耳的勸諫之言，心中常碰到不如意的不順之事，這正是切磋琢磨德行與事業的砥礪之石；倘若句句順耳、事事稱心，那就等於將自己一生的道德前程埋沒在毒酒危境中了。\",\"analysis\":\"【主題與背景】此段通過四種極具畫面感的自然景象，引導讀者體驗生命的「清純」與「活潑」。鶴唳與雞鳴打破了霜天與雪夜的寂靜，呈現出一種高潔而堅韌的精神力量，對應「乾坤清純之氣」。\\\\n【詞義與名物】鳥飛與魚戲則是理學家（如程顥「萬物靜觀皆自得」）與道家所推崇的自然「天機」，展現了生命本能的自由與舒展。\\\\n【思想與篇章】透過對這些景象的內省，人可以滌除心中的俗慮，與宇宙的生命力合流。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-7\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":7,\"canonicalText\":\"閒烹山茗聽瓶聲，爐內識陰陽之理；漫履楸枰觀局戲，手中悟生殺之機。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-7_s-1\",\"cai-gen-tan_ch-3_p-7_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"閒暇時烹煮著山中的清茶，靜聽茶水在茶瓶中咕嘟作響，從爐火與茶水交融的溫度中體會萬物陰陽調和的道理；隨意漫步到棋盤旁觀看他人對弈下棋，從棋子的起落佈局中領悟生死存亡、進退攻防的玄妙契機。\",\"analysis\":\"【題解與背景】\\\\n本段選自《菜根譚》〈評議〉第 153 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「閒烹山茗聽瓶聲爐內識陰陽之理漫履楸枰觀局……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「閒」、「烹」、「山」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《菜根譚》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：cai-gen-tan_ch-3_p-7）。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-8\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":8,\"canonicalText\":\"芳菲園林看蜂忙，覷破幾般塵情世態；寂寞衡茅觀燕寢，引起一種冷趣幽思。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-8_s-1\",\"cai-gen-tan_ch-3_p-8_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"在百花盛開、芳香四溢的園林裡，看著蜜蜂忙碌地飛舞採蜜，便能看穿世俗之人為了名利終日奔波勞碌的種種姿態；在冷清簡陋的茅草屋下，看著燕子安然地在巢中棲息，令人心中油然而生一種清冷超俗的趣味與幽深沉靜的思緒。\",\"analysis\":\"【主題與背景】本段出自《菜根譚》，透過自然景物的鮮明對比，抒發了作者看破世俗名利、嚮往清幽隱逸的心境。\\\\n【訓詁與名物】「芳菲」指花草茂盛、香氣濃鬱；「覷破」為看穿、看透；「塵情世態」指世間追名逐利的百態；「衡茅」指橫木為門、茅草為頂的簡陋房屋，代指隱士居所；「燕寢」指燕子安然棲息；「冷趣」指清冷超俗的審美趣味。\\\\n【章法與結構】全段採用對仗句式。「芳菲園林」對「寂寞衡茅」，「看蜂忙」對「觀燕寢」，形成繁華與清冷的強烈對比。前句從動態中「覷破」世俗的無謂盲動，後句從靜態中「引起」超脫的內在沈思，意境深遠。\\\\n【思想與義理】作者以「蜂忙」隱喻世人為名利終日奔波，最終只落得為他人作嫁衣裳，充滿了道家對世俗欲望的批判；而「燕寢」則象徵著放下執念後的內心安寧。這體現了《菜根譚》中典型的「出世與入世」哲學——在繁華中保持清醒，在寂寞中自得其樂。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-9\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":9,\"canonicalText\":\"會心不在遠，得趣不在多。盆池拳石間，便居然有萬裏山川之勢，片言隻語內，便宛然見萬古聖賢之心，纔是高士得眼界，達人得胸襟。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-9_s-1\",\"cai-gen-tan_ch-3_p-9_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"心領神會的境界並不在於追求遙遠的事物，獲得生命的情趣也不在於追求繁多的數量。在小小的盆景水池與拳頭般大小的石塊之間，便能展現出萬裡山川的雄偉氣勢；在隻言片語的簡單道理中，便能清晰看見萬古聖賢的真實心意。這才是高雅之士所具備的獨特眼界，也是豁達之人所擁有的開闊胸襟。\",\"analysis\":\"【主題與背景】此段體現了中國古典美學中「以小見大」、「納須彌於芥子」的核心思想。晚明文人喜愛微型園林、盆景與清言，其背後的哲學支撐是：萬物的本質並不取決於其物理尺度。\\\\n【詞義與名物】一個拳頭大的石頭可以具備泰山的精神，一句話可以概括千年的智慧。\\\\n【思想與篇章】這種「得趣不在多」的觀念，挑戰了世人對物質數量與空間規模的盲目追求，強調了內心感知能力與審美胸襟的決定性作用。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-10\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":10,\"canonicalText\":\"心與竹俱空，問是非何處安腳？貌偕松共瘦，知憂喜無由上眉。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-10_s-1\",\"cai-gen-tan_ch-3_p-10_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"我的心胸如同翠竹的內部一樣空虛無物，試問世間的恩怨是非又能在哪裡落腳紮根？我的面容與蒼松一樣清瘦古樸，明白世俗的憂愁與喜悅根本沒有理由爬上我的眉梢。\",\"analysis\":\"【題解與背景】\\\\n本段選自《菜根譚》〈評議〉第 156 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「心與竹俱空問是非何處安腳貌偕松共瘦知憂喜……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「心」、「與」、「竹」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《菜根譚》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：cai-gen-tan_ch-3_p-10）。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-11\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":11,\"canonicalText\":\"趨炎雖暖，暖後更覺寒威；食蔗能甘，甘餘便生苦趣。何似養志於清修而炎涼不涉，棲心於淡泊而甘苦俱忘，其自得為更多也。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-11_s-1\",\"cai-gen-tan_ch-3_p-11_s-2\",\"cai-gen-tan_ch-3_p-11_s-3\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"趨附權貴熱門雖然一時感到溫暖，但這短暫的溫暖過後，反而會讓人更深地感受到世態炎涼的徹骨寒冷；喫甘蔗雖然覺得甘甜，但甜味消逝後，口中便會產生酸苦的餘味。這哪裡比得上在清高貞潔的修行中涵養心志，從而不受世態炎涼的幹擾；將心靈寄託於恬靜淡泊之中，從而忘卻物質的甘甜與艱苦，如此一來，內心所獲得的悠然自得反而會更加深厚啊。\",\"analysis\":\"【題解與背景】\\\\n本段選自《菜根譚》〈評議〉第 157 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「趨炎雖暖暖後更覺寒威食蔗能甘甘餘便生苦趣……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「趨」、「炎」、「雖」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《菜根譚》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：cai-gen-tan_ch-3_p-11）。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-12\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":12,\"canonicalText\":\"席擁飛花落絮，坐林中錦繡團裀；爐烹白雪清冰，熬天上玲瓏液髓。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-12_s-1\",\"cai-gen-tan_ch-3_p-12_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"在落花飛絮鋪滿大地的林間席地而坐，就如同坐在大自然鋪設的錦繡地毯上一般；在爐火上烹煮著潔白的雪花與清澈的冰塊，彷彿是在熬煮著天上的仙家玉液與玲瓏精髓。\",\"analysis\":\"【題解與背景】\\\\n本段選自《菜根譚》〈評議〉第 158 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「席擁飛花落絮坐林中錦繡團裀爐烹白雪清冰熬……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「席」、「擁」、「飛」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《菜根譚》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：cai-gen-tan_ch-3_p-12）。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-13\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":13,\"canonicalText\":\"逸態閒情，惟期自尚，何事外修邊幅；清標傲骨，不願人憐，無勞多買胭脂。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-13_s-1\",\"cai-gen-tan_ch-3_p-13_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"閒適超脫的姿態與安逸的情懷，只求自己內心的尊崇與欣賞，又何必去刻意修飾外表、迎合世俗呢？清高出俗的標準與孤傲不羣的骨氣，絕不希望得到世人的同情與憐憫，更無須勞煩多買些胭脂俗粉來裝扮自己。\",\"analysis\":\"【主題與背景】本段出自《菜根譚》，強烈宣示了傳統文人追求內在獨立、拒絕迎合世俗審美的孤傲情懷。\\\\n【訓詁與名物】「逸態閒情」指閒適超脫的神態與情致；「自尚」即自我期許、自我欣賞；「修邊幅」指刻意修飾外表、講究儀表；「清標傲骨」指高潔的風度與不屈的性格；「胭脂」借指虛偽的粉飾與世俗的討好。\\\\n【章法與結構】本段採用嚴整的駢文對仗。「逸態閒情」對「清標傲骨」，「惟期自尚」對「不願人憐」。上下兩句皆以反問或否定句式（何事、無勞）作結，語氣堅定孤傲，徹底否定了逢迎世俗的行為。\\\\n【思想與義理】此段宣示了中國傳統文人的人格獨立宣言。真正的君子，其內在修為與高尚品格是為了對得起自己的本心（惟期自尚），而非為了博取外界的讚賞與憐憫。作者將迎合世俗比作「買胭脂」，展現了對虛偽名教與媚俗作風的極度蔑視，充滿了傲岸不羈的魏晉風度。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-14\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":14,\"canonicalText\":\"天地景物，如山間之空翠，水上之漣漪，潭中之雲影，草際之煙光，月下之花容，風中之柳態。若有若無，半真半幻，最足以悅人心目而豁人性靈。真天地間一妙境也。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-14_s-1\",\"cai-gen-tan_ch-3_p-14_s-2\",\"cai-gen-tan_ch-3_p-14_s-3\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"大自然中的景物，例如山林間那若隱若現的空濛翠色、水面上輕輕泛起的細微漣漪、深潭中倒映的悠悠雲影、草地邊飄忽的淡淡煙霧、月光下花朵的嬌柔容顏，以及清風中柳樹的婀娜姿態。這些景象若有若無，半真半幻，最能夠取悅人的耳目，並使人的性靈開闊澄澈。這真是天地之間最奇妙的意境了。\",\"analysis\":\"【題解與背景】\\\\n本段選自《菜根譚》〈評議〉第 160 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「天地景物如山間之空翠水上之漣漪潭中之雲影……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「天」、「地」、「景」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《菜根譚》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：cai-gen-tan_ch-3_p-14）。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-15\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":15,\"canonicalText\":\"「樂意相關禽對語，生香不斷樹交花」，此是無彼無此的真機。「野色更無山隔斷，天光常與水相連」，此是徹上徹下的真境。吾人時時以此景象注之心目，何患心思不活潑，氣象不寬平！\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-15_s-1\",\"cai-gen-tan_ch-3_p-15_s-2\",\"cai-gen-tan_ch-3_p-15_s-3\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"狂風暴雨之時，連飛鳥都會感到憂傷不安；日光煦暖風和日麗之際，連草木都會展現欣欣向榮的生機。由此可知，天地之間絕對不能一日缺乏祥和之氣，人的內心也絕對不能一日缺乏和樂喜悅的情致。\",\"analysis\":\"【主題與背景】此段融合了宋代理學的「生意」與禪宗的「無分別境」。前半句借用宋代詩人林逋的詩句，描繪了自然界萬物和諧共生、無物我之分的「真機」。\\\\n【詞義與名物】後半句則以水天相連的宏大景緻，隱喻心胸的豁然開朗、無所滯礙的「真境」。\\\\n【思想與篇章】作者提出，通過對自然和諧與無限意象的冥想（注之心目），人可以打破自我中心的狹隘心智，培育出如天地般寬廣、如春天般活潑的心靈氣象。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-16\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":16,\"canonicalText\":\"鶴唳、雪月、霜天、想見屈大夫醒時之激烈；鷗眠、春風、暖日，會知陶處士醉裏之風流。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-16_s-1\",\"cai-gen-tan_ch-3_p-16_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"仙鶴唳鳴、冰雪明月、寒霜漫天，讓人聯想到屈原大夫獨醒於世時，那份憂國憂民的激烈情懷；海鷗安眠、春風和煦、暖日融融，能讓人領會到陶淵明處士在醉意朦朧中，那份超然物外、瀟灑自得的儒雅風流。\",\"analysis\":\"【主題與背景】此段將自然意象與歷史人物的精神品格相結合，展現了中國文人的兩大核心精神路徑：悲壯的抗爭與超然的隱逸。「鶴唳、雪月、霜天」是冷峻、孤傲而激越的，象徵了屈原「舉世皆濁我獨清，眾人皆醉我獨醒」的崇高愛國主義與道德堅持；「鷗眠、春風、暖日」則是溫暖、和諧而放鬆的，象徵了陶淵明「採菊東籬下，悠然見南山」的忘我消融。\\\\n【詞義與名物】這兩種人格交相輝映，構成中國知識分子在出世與入世間的精神坐標。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-17\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":17,\"canonicalText\":\"黃鳥情多，常向夢中呼醉客；白雲意懶，偏來僻處媚幽人。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-17_s-1\",\"cai-gen-tan_ch-3_p-17_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"黃鶯似乎多情，常常在啼鳴中呼喚夢鄉裡的醉酒之客；白雲顯得慵懶，偏偏喜歡飄落到偏僻幽深的地方，來取悅陪伴隱居的幽雅之人。\",\"analysis\":\"【主題與背景】本段出自《菜根譚》，描寫了隱逸者與自然景物之間的精神共鳴，展現出極高的詩意與道家情懷。\\\\n【訓詁與名物】「黃鳥」即黃鶯，常於春日啼鳴；「醉客」指飲酒入夢、忘卻世俗煩憂的人；「意懶」形容白雲悠閒舒捲、毫無機心的狀態；「媚」此處作親近、取悅解；「幽人」指隱居的高士。\\\\n【章法與結構】這是一副極具詩情畫意的對聯式短文。「黃鳥情多」對「白雲意懶」，「呼醉客」對「媚幽人」。作者運用擬人手法，將自然景物賦予了人的情感與意向，使得整段文字生機盎然、情景交融。\\\\n【思想與義理】段落描繪了一幅人與自然和諧共鳴的隱逸圖景。在隱士眼中，自然界並非無情之物，黃鳥會深情喚醒醉客，白雲會特意來陪伴幽人。這反映了道家「萬物與我為一」的宇宙觀，當人放下世俗機心，自然便成為最真誠的知己，給予隱士最深沉的精神撫慰。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-18\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":18,\"canonicalText\":\"棲遲蓬戶，耳目雖拘而神情自曠；納結山翁，儀文雖略而意念常真。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-18_s-1\",\"cai-gen-tan_ch-3_p-18_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"隱居在簡陋的蓬門草戶之中，雖然眼界與耳聞受到空間的侷限，但精神與情懷卻自然顯得曠遠開闊；結交山野裡的農夫老翁，雖然社交禮儀粗野簡陋，但彼此交往的意念與情誼卻始終真誠無偽。\",\"analysis\":\"【主題與背景】本段出自《菜根譚》，透過隱居生活的兩個面向，探討了物質簡約與精神豐盈之間的辯證關係。\\\\n【訓詁與名物】「棲遲」指隱居、退隱；「蓬戶」即茅草做成的門戶，代指貧寒住所；「拘」指受限；「曠」指開闊；「納結」指結交、往來；「山翁」指山野鄉間的老人；「儀文」指世俗客套的禮節儀式。\\\\n【章法與結構】全段以「棲遲蓬戶」與「納結山翁」兩種隱居生活情境並列。每一句皆採用「雖...而...」的轉折句型，先指出外在條件的匱乏（耳目拘、儀文略），再翻轉出內在精神的豐盈（神情曠、意念真），對比強烈。\\\\n【思想與義理】這段文字深刻闡釋了「物質與精神」、「形式與本質」的辯證關係。作者認為，居住環境的簡陋反而能讓人擺脫感官刺激的奴役，獲得靈魂的自由；而沒有繁文縟節的世俗社交，反而能保全人際交往中最寶貴的真誠。這正是返璞歸真的儒道融合境界。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-19\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":19,\"canonicalText\":\"滿室清風滿幾月，坐中物物見天心；一溪流水一山雲，行處時時觀妙道。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-19_s-1\",\"cai-gen-tan_ch-3_p-19_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"滿屋子裡吹佛著清涼的微風，整張几案上灑滿了皎潔的月光，靜坐之中，天地萬物都呈現出自然的造化本心；一溪潺潺流動的活水，一山緩緩飄蕩的雲彩，在行走之間，時時處處都能觀察到大自然的奧妙真諦。\",\"analysis\":\"【主題與背景】本段展現了儒家「萬物靜觀皆自得」與道家「道在瓦甓」的哲學境界。清風、明月、流水、山雲，這些平凡的自然現象在心靈澄澈的觀照下，皆化為「天心」的展示與「妙道」的載體。\\\\n【詞義與名物】不需要繁複的經疏論證，在日常生活與自然接觸的「坐中」與「行處」，便能直接體證宇宙的秩序與生命的和諧，是高度生活化的證道實踐。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-20\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":20,\"canonicalText\":\"炮鳳烹龍，放箸時與齏鹽無異；懸金佩玉，成灰處共瓦礫何殊。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-20_s-1\",\"cai-gen-tan_ch-3_p-20_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"即使是像烤鳳凰、煮神龍那般極其奢侈珍貴的盛宴，在放下筷子、飽腹之後，其實與喫粗鹽醃菜沒有什麼差別；即使是腰纏萬金、佩戴美玉那般極盡顯赫尊貴的身份，在肉身化為骨灰之後，與破碎的磚瓦碎石又有什麼不同呢？\",\"analysis\":\"【主題與背景】此段以強烈的誇張與對比，揭示了物質享受與世俗名譽的虛無本質。「炮鳳烹龍」是極致的口腹之慾，但「放箸」的一刻，生理滿足感便迅速退去，與最廉價的「齏鹽」（粗茶淡飯）無異，揭示了慾望的短暫與邊際效應遞減。\\\\n【詞義與名物】「懸金佩玉」是社會地位的頂峯，但在死亡（成灰）面前，皆化為烏有，與「瓦礫」同質。\\\\n【思想與篇章】這段話融合了佛教的「無常」與「四大皆空」，勸導人們放下對物慾與名利的病態執著。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-21\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":21,\"canonicalText\":\"「掃地白雲來」，纔著工夫便起障。「鑿池明月入」，能空境界自生明。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-21_s-1\",\"cai-gen-tan_ch-3_p-21_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"「剛把地面打掃乾淨，白雲便飄落過來」，這說明如果過於刻意、執著於用功修行，反而會升起心靈的障礙。「只要把池塘開鑿出來，明月便自然倒映其中」，這說明只要能放空心靈、清除雜念，智慧的光明自然就會顯現。\",\"analysis\":\"【主題與背景】此段是探討禪宗修持方法論的精妙語錄。「掃地白雲來」比喻刻意清除雜念、執著於「修法」的作為，這種「著工夫」的執著本身就是一種妄想（法執），反而會遮蔽本自清淨的自性（起障）。\\\\n【詞義與名物】「鑿池明月入」則象徵「無為」與「借假修真」，池塘代表心靈的空容器，只要心能放空、虛懷若谷，代表智慧佛性的「明月」自然會不求自得地顯現。\\\\n【思想與篇章】這強調了「無修之修」、順應自然的心靈解脫路徑。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-22\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":22,\"canonicalText\":\"造化喚作小兒，切莫受渠戲弄；天地尤為大塊，須要任我爐錘。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-22_s-1\",\"cai-gen-tan_ch-3_p-22_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"如果把主宰命運的造物主當作一個頑皮的小孩，那麼我們千萬不要輕易受到他的戲弄與擺佈；天地雖然是一個巨大的鎔爐，但我們必須擁有主動權，任由自己去鍛造磨煉生命。\",\"analysis\":\"【主題與背景】此段展現了《菜根譚》中罕見的、具有主動抗爭色彩的精神力量。雖然《菜根譚》多講隨緣與閒逸，但在此處卻表現出儒家「我命在我不在天」的主體性與道家「盜天地之機」的豪情。\\\\n【詞義與名物】作者將命運造化謔稱為「小兒」，警示世人不要被命運的無常喜怒所左右；並主張將天地萬物當作鍛煉自我的「爐錘」，主動在苦難與變化中錘煉人格，展現了強大的生命意志與主體自覺。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-23\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":23,\"canonicalText\":\"想到白骨黃泉，壯士之肝腸自冷；坐老清溪碧嶂，俗流之胸次亦閒。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-23_s-1\",\"cai-gen-tan_ch-3_p-23_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"一旦想到自己終將化為荒郊白骨、歸於九泉之下，即使是雄心萬丈的壯士，其爭名奪利的心腸也會自然冷卻；如果能長期靜坐在清澈溪流與翠綠山巒之中，即使是終日追逐名利的俗人，其胸懷與心境也會變得安詳清閒。\",\"analysis\":\"【主題與背景】此段探討了死亡反思與自然環境對心靈的淨化作用。「白骨黃泉」是佛教「白骨觀」與「無常觀」的直觀體現。\\\\n【詞義與名物】當人直面死亡的必然性，世俗的野心與熱情（壯士肝腸）便會失去意義而冷卻，從而獲得超越的視角。\\\\n【思想與篇章】「清溪碧嶂」則是自然的療癒力量，大自然的寂靜與永恆能夠消解「俗流」（市儈之輩）胸中的焦慮與市儈，使其回歸寧靜。這體現了道家以自然滌蕩心胸的實踐路徑。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-24\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":24,\"canonicalText\":\"夜眠八尺，日啖二升，何須百般計較；書讀五車，才分八斗，未聞一日清閒。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-24_s-1\",\"cai-gen-tan_ch-3_p-24_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"晚上睡覺不過需要八尺寬的牀鋪，白天吃飯不過喫下二升的米糧，又何必千方百計、百般計較名利得失呢？即使能夠讀破五車藏書、才華橫溢富比八斗，如果整天陷於心機操勞，也從未聽說能獲得過一天的清閒。\",\"analysis\":\"【主題與背景】此段以極具對比性的生活算術，反思了物質需求與精神負擔的關係。前半句指出人類基本的生理需求（夜眠八尺，日啖二升）是極其有限的，超出此限度的百般計較皆是貪欲作祟，呼應了《莊子·逍遙遊》中「鷦鷯巢於深林，不過一枝；鼴鼠飲河，不過飽腹」的觀念。\\\\n【詞義與名物】後半句則指出，追求世俗的知識與才華（讀書五車、才分八斗），若演變為炫耀與爭逐的工具，反而會讓人失去生命最寶貴的「清閒」，得不償失。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-25\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":25,\"canonicalText\":\"君子之心事，天青日白，不可使人不知；君子之才華，玉韞珠藏，不可使人易知。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-25_s-1\",\"cai-gen-tan_ch-3_p-25_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"君子的心思與胸懷，應當如同晴朗的青天、明亮的白日那樣光明磊落，沒有什麼不可以讓人知道的；君子的才華與能力，則應當如同深藏在原石中的美玉、隱匿在蚌殼裡的珍珠那般含蓄內斂，絕對不可以輕易向人炫耀、讓人一眼看穿。\",\"analysis\":\"【主題與背景】本段出自《菜根譚》，探討了君子在「心性修養」與「才華展現」上應當具備的兩種截然不同的態度。\\\\n【訓詁與名物】「心事」指內心的意念與思想；「天青日白」形容如同青天白日般光明磊落；「韞」音「蘊」，包藏之意；「玉韞珠藏」指像美玉與珍珠深藏在石中與蚌內一般，光華不外露。\\\\n【章法與結構】本段以「君子之...」開頭，形成工整的排比與對比。「心事」對「才華」，「天青日白」對「玉韞珠藏」，「不可使人不知」對「不可使人易知」。一顯一隱，節奏明快，哲理深刻。\\\\n【思想與義理】此段極其精準地概括了儒家君子修身處世的兩大核心原則：在道德與心胸上，必須絕對坦蕩誠實，無事不可對人言（《大學》之慎獨）；但在才幹與鋒芒上，卻必須極度收斂剋制，大巧若拙。因為心事坦蕩能贏得信任，而才華內斂則能避免招忌，這體現了極高的人生智慧與中庸之道。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-26\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":26,\"canonicalText\":\"耳中常聞逆耳之言，心中常有拂心之事，纔是進德修行的砥石。若言言悅耳，事事快心，便把此生埋在鴆毒中矣。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-26_s-1\",\"cai-gen-tan_ch-3_p-26_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"耳朵裡經常聽到刺耳不順耳的話語，心裡經常遇到不如意不順心的事情，這才是用來磨礪道德、修行品格的磨刀石。如果聽到的每一句話都無比悅耳動聽，遇到的每一件事都無比順心如意，那實際上就是把自己的一生埋在致命的鴆毒之中了。\",\"analysis\":\"【題解與背景】\\\\n本段選自《菜根譚》〈評議〉第 172 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「耳中常聞逆耳之言心中常有拂心之事纔是進德……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「耳」、「中」、「常」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《菜根譚》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：cai-gen-tan_ch-3_p-26）。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-27\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":27,\"canonicalText\":\"疾風怒雨，禽鳥慼慼；霽月光風，草木欣欣，可見天地不可一日無和氣，人心不可一日無喜神。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-27_s-1\",\"cai-gen-tan_ch-3_p-27_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"面對狂風暴雨的惡劣天氣，連飛鳥都會感到憂傷悲慼；迎來雨過天晴的明月微風，草木都會呈現出生機勃勃的欣喜之態。由此可見，天地之間不可以一天沒有祥和之氣，而人的內心也不可以一天沒有喜悅與安詳的精神。\",\"analysis\":\"【主題與背景】此段藉由自然氣候對生物情緒的影響，論證了心靈和諧（喜神）的重要性。狂風暴雨（疾風怒雨）對應著憤怒、悲傷等負面情緒，會使生命力萎縮（禽鳥慼慼）；而雨過天晴（霽月光風）對應著慈悲、寬容與樂觀，能激發生命的無限生機（草木欣欣）。\\\\n【詞義與名物】宋代理學強調「涵養須用敬，進學在致知」，亦極看重內心的「和樂」狀態。\\\\n【思想與篇章】作者主張保持「喜神」，即是要求人在任何情況下都要維持內心的溫柔、祥和與生生不息的喜悅。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-28\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":28,\"canonicalText\":\"醲肥辛甘非真味，真味只是淡；神奇卓異非至人，至人只是常。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-28_s-1\",\"cai-gen-tan_ch-3_p-28_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"美酒佳餚、辛辣甘甜的濃烈味道並不是食物真正的美味，真正的美味其實只是清淡樸素的滋味；行為怪異、神通廣大的神奇之輩並不是修養達到極致的聖人，真正完美的至人其實只是像平常人一樣平凡無奇。\",\"analysis\":\"【主題與背景】此段融合了老子「淡乎其無味」與莊子「至人無己，神人無功，聖人無名」的思想。世人往往追求感官上的強烈刺激（醲肥辛甘）與行為上的標新立異（神奇卓異），但作者指出，那種繁華與奇特都是短暫且偏離本質的。\\\\n【詞義與名物】真正的真理蘊含在最普遍、最持久的「淡」與「常」之中。\\\\n【思想與篇章】「至人只是常」呼應了禪宗的「平常心是道」，修行的最高境界不是顯露神通或標榜高尚，而是將智慧消融於日常的穿衣吃飯與平凡生活之中。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-29\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":29,\"canonicalText\":\"夜深人靜獨坐觀心；始知妄窮而真獨露，每於此中得大機趣；既覺真現而妄難逃，又於此中得大慚忸。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-29_s-1\",\"cai-gen-tan_ch-3_p-29_s-2\",\"cai-gen-tan_ch-3_p-29_s-3\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"在夜深人靜的時候獨自靜坐、反省內心，這才體會到當一切世俗妄念平息時，真實的本性便會獨自顯露出來，每次在這種境界中都能獲得極大的生命天機與樂趣；然而，當察覺到真實本性顯現時，卻也發現自己平時的種種妄念與習氣依然難以完全逃離，又每次在這種反思中產生極大的慚愧與羞愧。\",\"analysis\":\"【主題與背景】此段是一篇極具深度的禪修與道德內省日記。作者描述了「獨坐觀心」的兩個心靈層次。\\\\n【詞義與名物】第一層次是「妄窮真露」，當外境寂靜，大腦的攀緣心停息，自性的光明與喜悅自然現前，這是禪定的「大機趣」。\\\\n【思想與篇章】第二層次則是「真現妄難逃」，在真如自性的對照下，修行者會敏銳地察覺到自己深層的潛意識中仍藏有微細的妄想與自私（習氣），因而產生深刻的「大慚忸」（慚愧）。這種真妄交織的自我剖析，體現了修行過程中的誠實與精進。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-30\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":30,\"canonicalText\":\"恩裏由來生害，故快意時須早回頭；敗後或反成功，故拂心處切莫放手。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-30_s-1\",\"cai-gen-tan_ch-3_p-30_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"恩惠之中往往會衍生出禍害，因此在春風得意、感到暢快的時候，必須及早回頭反省，不可過分沉迷；失敗之後有時反而能夠轉為成功，所以在遭遇挫折、事與願違的時候，千萬不要輕易放棄。\",\"analysis\":\"【訓詁與名物】：「恩裏」指恩惠、寵信之中。「由來」意為歷來、往往。「生害」指產生禍患。「快意」指稱心如意、高興暢快。「拂心」指不順心、違背心意。「切莫」意為千萬不要。「放手」指放棄。此句用詞質樸而富有哲理，對比了「恩與害」及「敗與成」的辯證關係。\\\\n\\\\n【章法與結構】：此段採用對偶的句式結構，前一句「恩裏由來生害，故快意時須早回頭」與後一句「敗後或反成功，故拂心處切莫放手」形成工整的對比。前後兩部分皆是先陳述客觀的規律（恩中生害、敗後成功），然後點出在這種情況下應有的態度與做法（早回頭、莫放手），邏輯嚴密，語氣懇切。\\\\n\\\\n【思想與義理】：此段蘊含著深厚的道家辯證思想與儒家進退之智。「恩裏生害」告誡人們在順境與受寵之際要保持警惕，懂得急流勇退，避免因過分得意而招致災禍，體現了「物極必反」的道理；「敗後反成功」則勉勵人們在逆境與挫折中要堅韌不拔，看到希望與轉機，不輕言放棄。這種居安思危、處變不驚的處世哲學，對於修身養性有著極大的指導意義。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-31\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":31,\"canonicalText\":\"藜口莧腸者，多冰清玉潔；袞衣玉食者，甘婢膝奴顏。蓋志以淡泊明，而節從肥甘喪矣。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-31_s-1\",\"cai-gen-tan_ch-3_p-31_s-2\",\"cai-gen-tan_ch-3_p-31_s-3\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"喫著粗茶淡飯、喫藜莧等野菜度日的人，大多品格高尚，像冰一樣清澈、如玉一般聖潔；穿著華麗禮服、享受珍饈美味的人，反而往往甘心奴顏婢膝、諂媚討好權貴。這大概是因為高尚的志向要在恬靜淡泊中才能顯明，而做人的氣節往往是在追求肥美甘甜的物質享受中喪失殆盡的。\",\"analysis\":\"【主題與背景】此段是關於物質享受與道德操守的道德訓誡，直接承襲了諸葛亮《誡子書》中「非淡泊無以明志，非寧靜無以致遠」的精神。作者以強烈的社會觀察對比，指出物質生活的匱乏（藜口莧腸）往往能保全人格的獨立與純潔，而對物質享受（袞衣玉食）的病態追求，則會使人喪失尊嚴，淪為權力的奴才（婢膝奴顏）。\\\\n【詞義與名物】這警示人們要警惕物慾對靈魂的腐蝕。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-32\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":32,\"canonicalText\":\"面前的田地要放得寬，使人無不平之嘆；身後的惠澤要流得長，使人有不匱之思。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-32_s-1\",\"cai-gen-tan_ch-3_p-32_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"在自己面前的道路與天地要放得寬廣一些，讓別人也能有路可走，從而使人不會產生憤懣不平的感嘆；留在自己身後的恩惠與德澤要流傳得長遠一些，讓後人能夠無窮無盡地享用，從而使人產生源源不絕的思慕與感念。\",\"analysis\":\"【訓詁與名物】：「田地」在此並非指真實的農田，而是比喻人生的境界、活動空間與處事尺度。「放得寬」指心胸開闊、做事留有餘地。「不平之嘆」指因為遭受不公正待遇而產生的抱怨與嘆息。「惠澤」指恩惠、德澤。「不匱」意為不缺乏、不窮盡，語出《詩經·大雅·既醉》：「孝子不匱，永錫爾類」。「思」指思念、緬懷。\\\\n\\\\n【章法與結構】：全段以工整的對仗形式呈現，「面前的田地」對應「身後的惠澤」，「放得寬」對應「流得長」，「使人無不平之嘆」對應「使人有不匱之思」。空間上的「面前」與時間上的「身後」交織，橫向的寬廣與縱向的長遠相映成趣，形式優美且意蘊深遠。\\\\n\\\\n【思想與義理】：這段話強調了為人處世的胸襟與目光。「放得寬」體現了寬容大度與與人為善的儒家忠恕之道，不與人爭利，不把人逼入絕境，社會才能和諧；「流得長」則要求我們不僅關注眼前的得失，更要考慮長遠的影響與身後的名聲，積德行善，為後人造福。這是一種超越了個人私利、追求精神不朽與境界昇華的高尚人生觀。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-33\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":33,\"canonicalText\":\"路徑窄處留一步，與人行；滋味濃的減三分，讓人嗜。此是涉世一極樂法。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-33_s-1\",\"cai-gen-tan_ch-3_p-33_s-2\",\"cai-gen-tan_ch-3_p-33_s-3\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"在道路狹窄的地方，要停下來留出一步的空間，讓別人也能夠通行；在品嚐濃鬱甘美的滋味時，要減少三分的貪戀，分給別人去品嚐。這就是為人處世的一種能帶來極大快樂的法則。\",\"analysis\":\"【訓詁與名物】：「路徑窄處」喻指人生中遭遇利益衝突、競爭激烈的情況。「留一步」指退讓、包容。「滋味濃」比喻世間名利、物質享受等極具誘惑力的事物。「三分」泛指一部分，非確指。「嗜」意為喜好、享受。「涉世」指經歷世事、在社會上立身處世。「極樂法」指獲得最高快樂的方法與法門，帶有佛家色彩。\\\\n\\\\n【章法與結構】：段落先以兩個對仗的分句「路徑窄處留一步，與人行」和「滋味濃的減三分，讓人嗜」作鋪陳，分別從行為上的退讓和物質上的分享兩個角度舉例說明，最後以一句「此是涉世一極樂法」進行總結昇華，畫龍點睛，將具體的行為準則上升到了人生哲學的高度。\\\\n\\\\n【思想與義理】：本段融合了儒家的「讓」與道家、佛家的「捨」的思想。在人生競爭中主動退讓，在利益面前主動分享，看似是自己吃了虧，實則是化解矛盾、廣結善緣的智慧。作者指出，真正的快樂並非源於獨佔所有的好處與便利，而是來自於與人方便、與人分享。這種「退一步海闊天空」與「有福同享」的胸襟，能讓人擺脫患得患失的痛苦，從而獲得內心真正的寧靜與極大的快樂。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-34\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":34,\"canonicalText\":\"作人無甚高遠的事業，擺脫得俗情便入名流；為學無甚增益的工夫，減除得物累便臻聖境。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-34_s-1\",\"cai-gen-tan_ch-3_p-34_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"做人其實並沒有什麼高深莫測、難以企及的偉大事業，只要能夠擺脫世俗名利之情的羈絆，就能夠躋身於高雅的名士之流；做學問也沒有什麼不斷增加學識的特別功夫，只要能夠減除外在物質慾望的牽累，就能夠達到聖人的崇高境界。\",\"analysis\":\"【訓詁與名物】：「甚」意為什麼。「高遠」指高深長遠、難以企及。「俗情」指世俗的慾望、名利之心。「名流」指有聲望、品格高尚的人士。「為學」指做學問、修養品德。「增益」指增加、提升。「物累」指受外在物質與環境的牽引和拖累。「臻」意為達到。「聖境」指聖人所具有的高尚道德境界。\\\\n\\\\n【章法與結構】：這段文字使用了標準的對偶句式，「作人無甚高遠的事業」對「為學無甚增益的工夫」，「擺脫得俗情便入名流」對「減除得物累便臻聖境」。通過「無甚……便……」的句式，反覆強調了一種否定式的修養方法。前後兩句分別從「作人」與「為學」兩個維度切入，相輔相成，結構嚴謹，韻律和諧。\\\\n\\\\n【思想與義理】：此段深刻體現了道家「為道日損」與禪宗「明心見性」的思想。作者認為，無論是做人的境界還是學問的修養，都不在於向外去追求、獲取與積累，而在於向內去淨化、捨棄與做減法。摒棄了世俗的私慾與物質的牽累，人本有的清明本性就會自然顯露，從而自然而然地達到名士與聖人的境界。這是一種返璞歸真、清靜無為的修心哲學。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-35\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":35,\"canonicalText\":\"寵利毋居人前，德業毋落人後，受享毋踰分外，修持毋減分中。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-35_s-1\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"面對恩寵與利益，千萬不要搶在別人的前面去爭奪；面對道德修養與善行事業，千萬不要落在別人的後面去推諉；享受物質生活時，絕對不要超越自己本分之外的限度；在自我要求與道德修持上，也絕對不要減少自己應盡本分之中的工夫。\",\"analysis\":\"【主題與背景】此段是一組對稱的道德實踐格言，完美融合了儒家的義利之辨與謙讓之德。在「寵利」與「受享」等感官物慾層面，主張退讓、守分，避免貪婪與越軌；在「德業」與「修持」等精神提升層面，則主張主動、堅持，不甘落後。\\\\n【詞義與名物】這種「外退內進」的策略，既能在社會關係中防怨避禍，又能在個人人格完善上精進不懈，是儒家君子持身立德的典範。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-36\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":36,\"canonicalText\":\"處世讓一步為高，退步即進步的張本；待人寬一分是福，利人實利己的根基。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-36_s-1\",\"cai-gen-tan_ch-3_p-36_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"在社會上為人處世，能夠主動退讓一步是高明的表現，因為退讓往往就是為了日後進步所預留的伏筆；對待別人寬容一分便是一種福氣，因為給予他人便利與利益，實際上正是為將來有利於自己打下堅實的基礎。\",\"analysis\":\"【訓詁與名物】：「處世」指在社會上生活與交往。「讓一步」指在利益或衝突中不爭搶、作退讓。「高」指高明、境界高超。「張本」原指伏筆，這裡引申為基礎、前提與準備。「寬一分」指寬厚、包容。「福」指福氣、福報。「根基」指基礎。此處的用語淺白卻精準，點明瞭人際交往中的辯證關係。\\\\n\\\\n【章法與結構】：整段話由兩組對稱的覆句構成。「處世讓一步為高」與「待人寬一分是福」相對立，分別提出「讓」與「寬」的行為準則及其價值；隨後的「退步即進步的張本」與「利人實利己的根基」則是對前句的進一步解釋與深化，揭示了其中隱藏的因果規律。先果後因，說理透徹，令人信服。\\\\n\\\\n【思想與義理】：此段生動地闡釋了中國傳統哲學中「退與進」、「利人與利己」的辯證統一關係。老子說：「夫唯不爭，故天下莫能與之爭」，主動的退讓並非懦弱，而是一種以退為進的策略與海納百川的胸襟。寬容待人、利益他人，不僅能化解矛盾、建立良好的人際關係，最終也會讓自己獲得更多的回報與幫助。這是一種圓融無礙、充滿智慧的雙贏處世之道。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-37\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":37,\"canonicalText\":\"蓋世的功勞，當不得一個矜字；彌天的罪過，當不得一個悔字。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-37_s-1\",\"cai-gen-tan_ch-3_p-37_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"即使有超越世間所有人的偉大功勞，也抵消不了一個「傲」字所帶來的敗壞；即使犯下充滿天際的滔天大罪，也抵擋不住一個「悔」字所帶來的救贖。\",\"analysis\":\"【訓詁與名物】「蓋世」形容功勞極大，超越世間所有人，如項羽《垓下歌》有「力拔山兮氣蓋世」。「矜」意為驕傲、自大、自誇。「彌天」指滿天、漫天，形容罪過極大，無以復加。「當不得」意為抵擋不住、抵消不了。\\\\n【章法與結構】本句採用了極致的工整對仗結構。「蓋世的功勞」對應「彌天的罪過」，「當不得一個矜字」對應「當不得一個悔字」。前後兩句形成了強烈的對比反差，一正一反，一貶一褒，將「矜」的破壞力與「悔」的救贖力展現得淋漓盡致，極具格言的警策效果。\\\\n【思想與義理】此句深刻揭示了儒家與佛教交融的修心哲理。儒家強調「滿招損，謙受益」，再大的功勞一旦沾染了驕傲自滿，便會失去其光彩，甚至招致災禍。而佛教主張「苦海無邊，回頭是岸」、「放下屠刀，立地成佛」，真誠的懺悔具有不可思議的力量，能夠洗刷最深重的罪孽。這句話教導人們在順境與成功時必須保持謙卑，在犯錯與墮落時則不要放棄悔改的希望。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-38\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":38,\"canonicalText\":\"完名美節，不宜獨任，分些與人，可以遠害全身；辱行污名，不宜全推，引些歸己，可以韜光養德。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-38_s-1\",\"cai-gen-tan_ch-3_p-38_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"完美的聲譽與高尚的節操，不應當由自己一個人獨自佔有，應當分一些功勞與榮譽給他人，這樣可以遠離嫉恨與禍害、保全自身；屈辱的行為與汙濁的名聲，不應當全部推卸給他人，自己主動承擔一些責任，這樣可以收斂光芒、涵養自己的道德操守。\",\"analysis\":\"【主題與背景】此段是極具深度與魄力的道德實踐與全身之道。在名利面前，世人常爭功諉過，而作者卻反其道而行之，倡導「分名」與「攬過」。\\\\n【詞義與名物】「完名美節獨任」會招致眾怨，甚至引來君王或同僚的猜忌，分名於人是極高明的政治智慧與保護機制（遠害全身）。\\\\n【思想與篇章】「辱行污名全推」則顯得自私自利，而「引些歸己」不僅體現了擔當，更是「韜光養德」的逆境修行，能培養無比深厚的德行。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-39\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":39,\"canonicalText\":\"事事要留個有餘不盡的意思，便造物不能忌我，鬼神不能損我。若業必求滿，功必求盈者，不生內變，必招外憂。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-39_s-1\",\"cai-gen-tan_ch-3_p-39_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"處理任何事情都要保留一點迴旋的餘地，不要做得太過絕對，這樣造物主就不會嫉妒我，鬼神也不能損害我。如果事業一定要追求達到頂峯，功勞一定要追求圓滿無缺，那麼即使不發生內部的變故，也必然會招致外部的憂患。\",\"analysis\":\"【訓詁與名物】「有餘不盡」指留有餘地，不把事情做絕、不把話說死，也不追求絕對的完美。「造物」指造物主或大自然，古人認為天地造化有「忌盈」的特性。「盈」與「滿」同義，指充實到極點、沒有空隙。「內變」指內部產生的禍亂與變故；「外憂」指從外部招惹來的災禍與憂患。\\\\n【章法與結構】全段分為兩層，先從正面論述「留有餘地」的益處，點明其能夠遠離天忌神損；接著從反面論述「求滿求盈」的危害，指出其必然導致內外災禍。正反對照，邏輯嚴密，說理透徹。「不能忌我」與「不能損我」並列，強化了安全感；「不生內變，必招外憂」則構成遞進的威脅，警示意味濃厚。\\\\n【思想與義理】這段話蘊含了深厚的道家「知足知止」與儒家「中庸之道」的哲理。《老子》雲：「持而盈之，不如其已；揣而銳之，不可長保。」《易經》中也有「日中則昃，月盈則食」的規律。萬事萬物一旦達到極點，必然會走向反面。因此，保持「有餘不盡」的狀態，不追求極致的圓滿，是一種避禍保身的智慧。這教導我們在人生追求中要懂得適可而止，不可過度貪婪或苛求完美，方能長久安泰。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-40\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":40,\"canonicalText\":\"家庭有個真佛，日用有種真道，人能誠心和氣、愉色婉言，使父母兄弟間形體兩釋、意氣交流，勝於調息觀心萬倍矣。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-40_s-1\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"家庭之中就存在著真正的佛菩薩，日常生活中就蘊含著真正的大道。人們如果能以真誠的心意和和藹的態度、愉悅的面容和溫婉的言語來對待家人，使得父母兄弟之間身心放鬆沒有芥蒂、彼此的情感意志能夠順暢交流，這種修行勝過打坐調息、靜坐觀心一萬倍。\",\"analysis\":\"【訓詁與名物】「真佛」指真正的覺悟者或神聖的存在，此處用以比喻家庭中的至高道德境界。「真道」指天地間的根本規律與真理。「愉色婉言」指和顏悅色與委婉柔和的言語，語出《禮記·祭義》之「和顏悅色」。「形體兩釋」意指彼此的身體與精神都感到放鬆、沒有拘束與隔閡。「調息觀心」是佛道兩教常見的修行方法，指調整呼吸與觀察內心念頭。\\\\n【章法與結構】本段採用先破後立、借指對比的手法。開篇即以「真佛」、「真道」這種崇高的宗教哲學概念，直接對應「家庭」與「日用」，極具震撼力。隨後具體描繪了實踐的方法（誠心和氣、愉色婉言）與達到的效果（形體兩釋、意氣交流）。最後以「勝於調息觀心萬倍矣」作結，用誇張的對比收束全段，點明主旨，餘味悠長。\\\\n【思想與義理】此句展現了宋明理學「道在日用倫常之中」的深刻思想，並融合了禪宗「擔水砍柴無非妙道」的境界。作者反對脫離現實生活去深山古廟中盲目尋求所謂的仙佛之道，而是強調在最平凡的家庭生活中、在處理與親人的關係中去修養心性。和睦的家庭關係、真誠的情感交流，本身就是最高級的修行。這體現了中國傳統文化重倫理、重實踐的入世精神，提醒人們珍惜眼前的親情，不要捨本逐末。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-41\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":41,\"canonicalText\":\"攻人之惡毋太嚴，要思其堪受；教人以善毋過高，當使其可從。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-41_s-1\",\"cai-gen-tan_ch-3_p-41_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"批評別人的過錯時不要太過嚴厲苛刻，必須考慮到對方在心理上是否能夠承受；教導別人行善時不要把標準定得太高，應當使對方在能力上能夠順利跟從與實踐。\",\"analysis\":\"【訓詁與名物】「攻」指攻擊、批評、指責。「惡」在此處指過失、錯誤或缺點。「堪受」意為能夠承受、可以接受。「教」指教導、勸勉。「善」指好的行為、道德標準。「可從」意為可以跟從、能夠做到。\\\\n【章法與結構】這是一副極為工整的對偶句。「攻人之惡」對應「教人以善」，「毋太嚴」對應「毋過高」，「要思其堪受」對應「當使其可從」。句式對仗勻稱，語氣平穩中正。前半句講如何糾正錯誤，後半句講如何引導向善，涵蓋了人際交往中勸導他人的兩個基本面向，邏輯嚴密。\\\\n【思想與義理】本段話體現了儒家「恕道」與「因材施教」的智慧。在人際交往和教育引導中，出發點雖好，但如果方法不當，往往適得其反。批評過於嚴厲，會傷害對方的自尊，導致逆反心理；要求過於高遠，會讓人產生畏難情緒，最終半途而廢。因此，真正的善意與有效的教育，必須建立在「同理心」的基礎上，設身處地為對方著想，考慮其心理承受能力和實際執行能力。這是一種充滿人情味與實用主義的處世哲學。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-42\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":42,\"canonicalText\":\"糞蟲至穢變為蟬，而飲露於秋風；腐草無光化為螢，而耀採於夏月。故知潔常自污出，明每從暗生也。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-42_s-1\",\"cai-gen-tan_ch-3_p-42_s-2\",\"cai-gen-tan_ch-3_p-42_s-3\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"生活在糞便中的幼蟲極度污穢，但蛻變為蟬之後，卻能在秋風中高潔地飲用露水；腐敗的野草本來沒有任何光澤，但化為螢火蟲之後，卻能在夏夜裡閃耀出明亮的光彩。由此可知，純潔的事物常常是從污穢中誕生出來的，而光明也每每是從黑暗中孕育而生的。\",\"analysis\":\"【訓詁與名物】「糞蟲」指在糞土中生長的幼蟲（古人誤以為蟬的幼蟲生於糞土中）。「穢」指骯髒、污濁。「腐草無光化為螢」源自古人的一種迷信觀念，認為螢火蟲是由腐草變化而來的（《禮記·月令》：「腐草為螢」）。「耀採」指閃耀光彩。「潔」指高潔、純潔。「明」指光明、明亮。\\\\n【章法與結構】全段採用了典型的「引證—結論」結構。前半部分通過「糞蟲變蟬」與「腐草化螢」兩個自然界（雖然是基於古人認知的）的現象，構成了一組生動的對偶句，不僅意象豐富（穢與潔、秋風與夏月對比），而且極具畫面感。後半部分以「故知」二字引出哲理性的結論，「潔常自污出，明每從暗生也」也是對仗句，將前面的具體現象昇華為抽象的哲學規律。\\\\n【思想與義理】這段文字充滿了辯證法思想，揭示了事物發展轉化的奇妙規律：美與醜、潔與污、明與暗並不是絕對孤立的，而是在一定條件下可以相互轉化的。周敦頤《愛蓮說》中「出淤泥而不染」亦是此理。這告訴我們，不要被事物暫時的、表面的低劣與困境所迷惑，即使身處卑微污濁的環境，也依然蘊含著昇華為高潔與光明的潛力。對於陷入逆境或出身微寒的人來說，這是一種極大的鼓勵，強調了內在生命力的突破與超越。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-43\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":43,\"canonicalText\":\"矜高倨傲，無非客氣降伏得，客氣下而後正氣伸；情慾意識，盡屬妄心消殺得，妄心盡而後真心現。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-43_s-1\",\"cai-gen-tan_ch-3_p-43_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"狂妄自大、傲慢無禮的態度，都不過是外在的不良情緒與浮躁之氣，只要將這股客氣降伏下去，浩然正氣自然會伸張；種種情感慾望與雜念，都屬於虛妄不實的心念，只要將這顆妄心消除消滅，純真本心自然就會顯現。\",\"analysis\":\"【主題與背景】本段以工整的對仗結構，分述「氣」與「心」的修養，融合了孟子與佛教的思想。\\\\n【訓詁與名物】「矜高倨傲」指狂妄自大、傲慢無禮；「客氣」指後天沾染的浮躁、傲慢等不良習氣；「正氣」指先天純潔剛正之氣；「妄心」指執著於情慾色相的虛妄雜念；「真心」指本自清淨的本然心性。\\\\n【章法與結構】本段以「矜高倨傲」對「情慾意識」，「客氣」對「妄心」，「正氣伸」對「真心現」。前後兩句皆採用「...無非...降伏得（消殺得），...而後...」的遞進句式，邏輯嚴密。\\\\n【思想與義理】此段融合了孟子的「養氣」說與佛教的「去妄顯真」論。修行的核心在於自我剋制與淨化：降伏外在浮躁的「客氣」以伸張內在的「正氣」，消除執著情慾的「妄心」以顯現清淨的「真心」。這是儒釋道三教合流在個人修養上的具體實踐。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-44\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":44,\"canonicalText\":\"飽後思味，則濃淡之境都消；色後思媱，則男女之見盡絕。故人當以事後之悔，悟破臨事之癡迷，則性定而動無不正。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-44_s-1\",\"cai-gen-tan_ch-3_p-44_s-2\",\"cai-gen-tan_ch-3_p-44_s-3\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"飽餐之後再回想食物的味道，那麼美味與清淡的感覺都會消失；情慾發洩後再思考淫樂之事，那麼對男女之色的渴望也會完全斷絕。所以人應當用事後的清醒與悔悟，來識破面臨誘惑時的執著與癡迷，如此一來，本性就能保持安定，而一舉一動就不會偏離正軌。\",\"analysis\":\"【主題與背景】此段借「食」與「色」這兩種人類最根本的欲望，闡明瞭破除執著的實踐方法。\\\\n【訓詁與名物】「思味」指回想食物的味道；「色後」指發洩情慾之後；「媱」同淫，指淫樂之事；「臨事之癡迷」指面臨誘惑時無法自拔的沉迷與執著；「性定」指本性安定不亂。\\\\n【章法與結構】全段分為兩層。前一層以「飽後思味」與「色後思淫」為例，指出欲望滿足後歸於空虛的普遍心理現象；後一層以「故」字承接，提煉出「以事後之悔，悟破臨事之癡迷」的修身法則，最後歸結於「性定而動無不正」的理想境界。\\\\n【思想與義理】人在「臨事」時易被欲望蒙蔽，但欲望滿足後往往會陷入空虛或悔悟。若能將這種「事後之悔」的清醒提前運用於面對誘惑的當下，便能看透欲望的虛幻，保持心性安定，從而做到舉止端正、不偏離正道。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-45\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":45,\"canonicalText\":\"居軒冕之中，不可無山林的氣味；處林泉之下，須要懷廊廟的經綸。處世不必徼功，無過便是功；與人不要感德，無怨便是德。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-45_s-1\",\"cai-gen-tan_ch-3_p-45_s-2\",\"cai-gen-tan_ch-3_p-45_s-3\",\"cai-gen-tan_ch-3_p-45_s-4\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"身處顯赫的官位與富貴之中，不能沒有嚮往山林野趣的超脫胸懷；隱居在山林泉水之下，應當懷抱治理國家的經邦濟世之才。處事不需要刻意追求功勞，沒有過失就是最大的功勞；待人不需要讓人感激自己的恩德，能做到不使人怨恨就是最大的恩德。\",\"analysis\":\"【主題與背景】本段由兩組對比構成，展現了出世與入世的互補，以及明哲保身的處世哲學。\\\\n【訓詁與名物】「軒冕」指古代大夫以上的車服，代指高官厚祿與繁華世俗；「山林的氣味」指隱逸超脫的情懷；「林泉」指隱士居住之地；「廊廟的經綸」指治理國家的政治才能與抱負；「徼功」即邀功，刻意謀求功勞；「感德」指使人感激自己的恩德。\\\\n【章法與結構】前一組對比「居軒冕」與「處林泉」，強調出世與入世心態的互補；後一組對比「處世」與「與人」，點出「無過便是功，無怨便是德」的消極而穩妥的處世哲學。\\\\n【思想與義理】前半段展現了儒道互補的理想人格：身處高位要有道家超脫名利的隱逸之心，隱居山林要有儒家兼濟天下的經世之志。後半段則提出了極具老莊色彩的避禍哲學，不刻意追求功名與恩德，只求無過無怨，體現了在複雜社會中明哲保身的圓融智慧。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-46\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":46,\"canonicalText\":\"憂勤是美德，太苦則無以適性怡情；淡泊是高風，太枯則無以濟人利物。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-46_s-1\",\"cai-gen-tan_ch-3_p-46_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"憂患勤勞雖然是優良的美德，但如果把自己弄得太過清苦，就無法調適性情、怡悅心情；淡泊名利雖然是高尚的風範，但如果過於枯槁死寂，就無法救濟他人、造福社會。\",\"analysis\":\"【主題與背景】此段深刻體現了儒家「執兩用中」的中庸之道，探討「憂勤」與「淡泊」兩種品格的尺度。\\\\n【訓詁與名物】「憂勤」指憂患意識與勤勉勞苦；「適性怡情」指順應本性、怡悅心情；「淡泊」指不求名利、清心寡慾；「枯」指枯槁死寂、毫無生氣；「濟人利物」指救濟他人、造福社會與萬物。\\\\n【章法與結構】全段以駢散結合的句式，分別探討兩種品格。句型皆為「...是...，太...則無以...」，先肯定其為美德與高風，隨即指出走向極端的流弊，邏輯清晰且充滿辯證色彩。\\\\n【思想與義理】勤勉與淡泊固然是高尚品德，但若過度走向極端（太苦、太枯），前者會壓抑生命活力，失去生活的樂趣；後者則會削弱對社會的關懷，變成冷漠自私。真正的修養應當是在自我怡情與社會擔當之間取得平衡。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-47\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":47,\"canonicalText\":\"事窮勢蹙之人，當原其初心；功成行滿之士，要觀其末路。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-47_s-1\",\"cai-gen-tan_ch-3_p-47_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"對於事業陷入困境、處境艱難的人，應當體諒並探尋他當初創業的善意與本心；對於功成名就、志得意滿的人，則要觀察他能否保持操守，安度晚年。\",\"analysis\":\"【主題與背景】本段論及評價人物與立身處世的法則，強調對不同處境之人的不同觀察視角。\\\\n【訓詁與名物】「事窮勢蹙」指事業失敗、處境極度艱難窘迫；「原」指推究、體諒；「初心」指最初發心與本意；「功成行滿」指功成名就、事業圓滿；「末路」指晚年的結局或最終的操守。\\\\n【章法與結構】此段以工整的對仗，對比了人生兩種極端狀態（失敗與成功）下的評價標準。「事窮勢蹙」對「功成行滿」，「原其初心」對「觀其末路」，言簡意賅，發人深省。\\\\n【思想與義理】對身處逆境、窮途末路者，應抱持寬容體諒之心，理解其初衷而不以成敗論英雄；對功成名就者，則需保持冷靜與警惕，觀察他能否善始善終、保持晚節。這展現了傳統文化中對弱者寬厚、對強者嚴格的人文關懷與歷史洞察。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-48\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":48,\"canonicalText\":\"富貴家宜寬厚而反忌剋，是富貴而貧賤，其行如何能享？聰明人宜斂藏而反炫耀，是聰明而愚懵，其病如何不敗！\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-48_s-1\",\"cai-gen-tan_ch-3_p-48_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"富貴人家本應該寬宏厚道，卻反而對人猜忌刻薄，這等於是身處富貴卻有著貧賤者的心態，這樣的行為怎麼能長久享有福報呢？聰明的人本應該收斂藏鋒，卻反而四處炫耀賣弄，這等於是看似聰明實則愚昧無知，這種毛病怎麼能不導致身敗名裂呢！\",\"analysis\":\"【訓詁與名物】「忌剋」指猜忌別人、刻薄寡恩。「貧賤」此處指心胸狹隘、缺乏福分的貧賤之相。「斂藏」指收斂鋒芒、隱藏才華。「炫耀」指誇耀、賣弄。「愚懵」即愚昧無知。「病」指缺點、弊病。【章法與結構】此段運用嚴整的對偶與反問句式。「富貴家」對「聰明人」，「宜寬厚」對「宜斂藏」，「反忌剋」對「反炫耀」，「富貴而貧賤」對「聰明而愚懵」，最後以「如何能享」與「如何不敗」的反問作結，語氣強烈，發人深省。【思想與義理】此句深刻揭示了德行與福報、才華與修養之間的關係。富貴者若無寬厚之德，則富貴不能長久；聰明者若無內斂之修養，則聰明反被聰明誤。這體現了《易經》中「滿招損，謙受益」的哲學思想，強調厚德載物與韜光養晦的重要性。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-49\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":49,\"canonicalText\":\"人情反覆，世路崎嶇。行不去，須知退一步之法；行得去，務加讓三分之功。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-49_s-1\",\"cai-gen-tan_ch-3_p-49_s-2\",\"cai-gen-tan_ch-3_p-49_s-3\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"人心世情變幻無常，社會的道路崎嶇坎坷。當遇到行不通的困境時，必須懂得退讓一步的方法與智慧；當事情進展順利、行得通的時候，務必再多加三分謙讓的功夫。\",\"analysis\":\"【訓詁與名物】「人情反覆」指世俗的人情冷暖變化無常。「世路崎嶇」比喻社會生活與人生道路充滿艱難險阻。「行不去」指遇到阻礙、走不通。「行得去」指進展順利、行得通。「讓三分」指保留餘地、不把事情做絕。【章法與結構】全段分為兩層，前兩句點明社會與人心的險惡複雜，後兩句則提出應對之策。「行不去」與「行得去」形成對比，分別對應「退一步之法」與「讓三分之功」，句式簡潔明快，對仗工整，極具格言的警策力。【思想與義理】此句體現了道家「退步原來是向前」的處世智慧與儒家「謙讓」的美德。在複雜的社會中，進退有度是保全自身的關鍵。受挫時退一步能海闊天空，得勢時讓三分能避免樹大招風。這種不走極端、留有餘地的中庸之道，是中國傳統文化中極為重要的生存哲學。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-50\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":50,\"canonicalText\":\"待小人不難於嚴，而難於不惡；待君子不難於恭，而難於有禮。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-50_s-1\",\"cai-gen-tan_ch-3_p-50_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"對待品行卑劣的小人，要做到嚴厲並不困難，困難的是在心裡不產生憎惡的情緒；對待品德高尚的君子，要做到恭敬並不困難，困難的是能做到符合禮節而不過度逢迎。\",\"analysis\":\"【訓詁與名物】「小人」指人格卑劣、唯利是圖的人。「惡」在此作動詞，指憎恨、厭惡。「君子」指品德高尚、修養深厚的人。「恭」指恭敬、順從。「有禮」指符合禮節的規範與法度，不卑不亢。【章法與結構】此段採用了「不難於……而難於……」的遞進句式，將「待小人」與「待君子」進行並列對比。前後兩句結構完全一致，層層深入，將外在的態度與內心的修養進行區分，邏輯嚴密，剖析入微。【思想與義理】此句探討了人際交往中的高級修養。對待小人，嚴厲是外在的防範，但若內心生出強烈的憎惡，則會擾亂自己的心境，甚至激化矛盾；對待君子，恭敬容易流於諂媚，唯有恪守「禮」的尺度，才能保持人格的獨立與尊嚴。這反映了儒家「和而不同」與修心養性的高超境界。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-51\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":51,\"canonicalText\":\"寧守渾噩而黜聰明，留些正氣還天地；寧謝紛華而甘淡泊，遺個清名在乾坤。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-51_s-1\",\"cai-gen-tan_ch-3_p-51_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"寧可保持質樸無華的狀態而摒棄世俗的機巧聰明，也要留存一些浩然正氣回報給天地；寧可拒絕繁華喧囂的物質享受而甘願過著清心寡慾的生活，也要留下一個清白高潔的美名在人間。\",\"analysis\":\"【訓詁與名物】「渾噩」即渾沌質樸，指天真純樸、不加修飾的本性。「黜」是摒棄、廢除。「紛華」指繁華喧囂、令人眼花繚亂的世俗誘惑。「淡泊」指不追求名利、生活清淡。「乾坤」本指天地，此處借指世間、人間。【章法與結構】此段以「寧……而……」的句式表達了強烈的價值抉擇。「守渾噩」對「謝紛華」，「黜聰明」對「甘淡泊」，「留些正氣」對「遺個清名」，「還天地」對「在乾坤」。對仗氣勢磅礴，展現出堅定不移的人生信念與崇高的精神追求。【思想與義理】此句融合了道家與儒家的核心價值觀。「守渾噩而黜聰明」呼應了老子「絕聖棄智」「見素抱樸」的思想，主張回歸人的自然本性；而「留正氣」「遺清名」則體現了儒家對身後名節與道德傳承的重視。這種超越物質與機智，追求精神永恆的境界，是中國古代知識份子的高尚追求。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-52\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":52,\"canonicalText\":\"降魔者先降其心，心伏則羣魔退聽；馭橫者先馭其氣，氣平則外橫不侵。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-52_s-1\",\"cai-gen-tan_ch-3_p-52_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"想要降伏外在的妖魔鬼怪，必須先降伏自己內心的邪念，內心一旦順服平靜，所有的妖魔自然就會退避順從；想要駕馭外來的橫逆災禍，必須先控制自己的脾氣，心氣一旦平和，外在的橫逆便無法侵擾。\",\"analysis\":\"【訓詁與名物】「降魔」本為佛教用語，指降伏惡魔，此處泛指克服外在的邪惡與困難。「退聽」指退避並聽從。「馭」指駕馭、控制。「橫」指意外的災禍、不合理的人事糾紛或蠻橫無理的對待。「氣平」指情緒穩定、心氣平和。【章法與結構】此段結構對稱，「降魔者」對「馭橫者」，「先降其心」對「先馭其氣」，「心伏」對「氣平」，「羣魔退聽」對「外橫不侵」。因果關係明確，邏輯嚴謹，將內在修為與外在結果緊密聯繫在一起。【思想與義理】這段話充滿了禪宗與儒家心性之學的哲理。它強調「向內求」的修煉方法，認為世間一切的困擾與橫逆，根源都在於自身的妄心與浮氣。只要能做到「心伏」與「氣平」，修築好內在的精神防線，外在的邪惡與困難便會失去作用。這體現了心性決定境遇的主觀能動性與高深的心靈修養。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-53\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":53,\"canonicalText\":\"養弟子如養閨女，最要嚴出入，謹交遊。若一接近匪人，是清凈田中下一不凈的種子，便終身難植嘉苗矣。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-53_s-1\",\"cai-gen-tan_ch-3_p-53_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"培養子弟如同撫養閨中少女一樣，最要緊的是嚴格限制他們的出入，謹慎選擇他們的交往對象。如果一旦接近品行不端的人，就像是在清淨的農田中播撒了不潔淨的種子，這輩子就再也難以培育出優秀的莊稼了。\",\"analysis\":\"【主題與背景】此段強調了早期家庭教育與環境薰陶的決定性作用，以生動的比喻說理。\\\\n【訓詁與名物】「弟子」此處泛指子弟、晚輩；「閨女」指未出嫁的少女；「匪人」指品行不端、非正派的人；「嘉苗」指優良的莊稼，喻指良好的品德與成就。\\\\n【章法與結構】先將「養弟子」比作「養閨女」，強調門禁與交友的嚴格；接著以「清淨田」比喻子弟純潔的心靈，以「不淨的種子」比喻不良的影響，論證一旦交友不慎，將會造成終身無法挽回的後果。\\\\n【思想與義理】青少年時期心智尚未成熟，極易受外界環境與同儕影響，因此防微杜漸、謹慎交遊至關重要。這與「孟母三遷」及「墨子悲絲」的教育理念一脈相承，提醒家長與教育者必須嚴格把關子弟的成長環境。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-54\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":54,\"canonicalText\":\"欲路上事，毋樂其便而姑為染指，一染指便深入萬仞；理路上事，毋憚其難而稍為退步，一退步便遠隔千山。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-54_s-1\",\"cai-gen-tan_ch-3_p-54_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"對於情慾誘惑之事，切不要因為一時的便利或好處就姑且嘗試，一旦沾染就會墜入萬丈深淵；對於實踐天理道義之事，切不要因為害怕困難而稍微有所退縮，一旦退縮就會與真理相隔千山萬水。\",\"analysis\":\"【主題與背景】此段剖析了人在面對誘惑與挑戰時的心理弱點，是一則在義利關頭必須保持高度警惕的修身箴言。\\\\n【訓詁與名物】「欲路」指順應個人私欲與感官誘惑的道路；「染指」比喻沾取非分之物或參與不當之事；「萬仞」形容極深，比喻墜入無底深淵；「理路」指踐行天理道義與道德規範的道路；「憚」為害怕、畏懼。\\\\n【章法與結構】全段以「欲路」與「理路」構成嚴整的對比。「毋樂其便」對「毋憚其難」，「一染指」對「一退步」，「深入萬仞」對「遠隔千山」。通過強烈的空間落差感，具象化了道德抉擇的後果。\\\\n【思想與義理】順應欲望往往看似容易便利，但稍一放縱便會越陷越深、不可自拔；而踐行道義往往充滿艱辛，但若稍有退縮畏難，便會離真理越來越遠。此言強調了防微杜漸與持之以恆的重要性。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-55\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":55,\"canonicalText\":\"念頭濃者自待厚，待人亦厚，處處皆厚；念頭淡者自待薄，待人亦薄，事事皆薄。故君子居常嗜好，不可太濃艷，亦不宜太枯寂。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-55_s-1\",\"cai-gen-tan_ch-3_p-55_s-2\",\"cai-gen-tan_ch-3_p-55_s-3\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"心思熱情濃厚的人，對待自己寬厚，對待他人也寬厚，所作所為都顯得寬厚；心思冷淡孤介的人，對待自己刻薄，對待他人也刻薄，處理事情都顯得刻薄。因此，君子日常的愛好與生活態度，既不可以過於濃烈艷麗，也不適宜過於枯燥寂寞。\",\"analysis\":\"【主題與背景】此段從心理學角度剖析了「念頭」的濃淡對人際關係與處世態度的深遠影響。\\\\n【訓詁與名物】「念頭」指心中的慾念或對事物的執著程度；「濃」指熱情、濃烈、執著；「厚」指寬厚、豐厚；「淡」指冷淡、疏離；「薄」指刻薄、微薄；「濃艷」指欲望強烈、追求奢華；「枯寂」指過於冷漠、毫無生氣。\\\\n【章法與結構】全段採用層層推進的說理結構。先對比「念頭濃」與「念頭淡」所導致的不同行為模式（自待、待人、處事）；接著以「故」字轉折，推導出君子在日常嗜好上應當遵循的原則——既不可太濃艷，也不宜太枯寂。\\\\n【思想與義理】過於熱情執著，容易沉溺於物慾與情感而失去理智；過於冷漠超脫，則容易走向自私刻薄而缺乏人情味。因此，真正的君子修養在於把握「中庸之道」，在嗜好與操守上保持溫和的平衡。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-56\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":56,\"canonicalText\":\"彼富我仁，彼爵我義，君子故不為君相所牢籠；人定勝天，志壹動氣，君子亦不受造化之陶鑄。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-56_s-1\",\"cai-gen-tan_ch-3_p-56_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"他人擁有財富，而我堅守仁德；他人擁有爵位，而我恪守義理。所以君子絕不會被帝王將相的名利所籠絡羈絆；人的意志能戰勝自然，意志專一就能引導氣魄。因此君子也絕不會受命運和造化的擺佈與塑造。\",\"analysis\":\"【主題與背景】此段高揚了儒家君子的獨立人格與浩然正氣，展現其超越名利與宿命的生命境界。\\\\n【訓詁與名物】「牢籠」指籠絡、羈絆與控制；「人定勝天」指人的堅定意志與努力可以戰勝自然或命運的安排；「志壹動氣」語出《孟子》，指意志專一就能引導和改變氣魄；「造化」指大自然或命運的創造者；「陶鑄」指塑造與化育。\\\\n【章法與結構】前半段對比世俗的名利（富、爵）與君子的道德（仁、義），得出君子不被權貴控制的結論；後半段則引用「人定勝天」與孟子名言，得出君子不被命運擺佈的結論。上下兩層皆展現了極強的自主性與抗爭精神。\\\\n【思想與義理】君子之所以能不屈服於權力的威逼利誘（不為君相所牢籠），是因為擁有內在的道德自信（仁義）；之所以能不屈服於命運的捉弄（不受造化之陶鑄），是因為擁有強大的精神意志。這是一種超越了世俗名利與自然宿命的抗爭精神。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-57\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":57,\"canonicalText\":\"立身不高一步立，如塵裏振衣、泥中濯足，如何超達？處世不退一步處，如飛蛾投燭、羝羊觸藩，如何安樂？\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-57_s-1\",\"cai-gen-tan_ch-3_p-57_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"立身行事如果不站在高人一等的境界，就像在灰塵中抖衣服、在泥潭中洗雙腳，怎麼可能超凡脫俗？為人處事如果不站在退讓一步的立場，就像飛蛾撲向蠟燭、公羊用角撞擊籬笆，怎麼可能獲得平安快樂？\",\"analysis\":\"【主題與背景】此段論述了「立身要高，處世要退」的雙重智慧，以生動的比喻點出盲目執著的危險。\\\\n【訓詁與名物】「立身」指在社會中樹立自我、安身立命；「振衣」指抖落衣服上的灰塵；「濯足」指洗腳；「超達」指超凡脫俗、通達明理；「羝羊觸藩」語出《易經·大壯卦》，公羊用角撞擊籬笆，角被卡住進退不得，比喻陷入困境。\\\\n【章法與結構】本段以兩個生動的比喻句並列構成。「立身不高」與「塵裏振衣、泥中濯足」相呼應，強調越弄越髒的徒勞；「處世不退」與「飛蛾投燭、羝羊觸藩」相呼應，強調自取滅亡與進退維谷的危險。最後皆以「如何...」的反問句作結，語氣強烈。\\\\n【思想與義理】立身若無高遠的志向與超越世俗的眼界，便會陷入名利的泥淖中無法自拔；處世若不懂得退讓包容，一味逞強好勝，就會招致災禍與困境。唯有內心高潔超脫，外在圓融退讓，方能獲得真正的安樂。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-58\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":58,\"canonicalText\":\"學者要收拾精神並歸一處。如修德而留意於事功名譽，必無實詣；讀書而寄興於吟詠風雅，定不深心。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-58_s-1\",\"cai-gen-tan_ch-3_p-58_s-2\",\"cai-gen-tan_ch-3_p-58_s-3\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"學習的人必須收斂心神，將精力集中在同一個地方。例如修養品德卻總是牽掛著建功立業和獲取名聲，必然無法達到真實的造詣；讀書做學問卻總是將興趣寄託在吟詩作對等風雅之事上，心思肯定無法深入專精。\",\"analysis\":\"【訓詁與名物】「收拾精神」指收斂心神，集中注意力。「實詣」指真實的造詣與成就。「寄興」指寄託興趣與情懷。「吟詠風雅」指作詩填詞等附庸風雅之事。「深心」指心思深入，專心致志。\\\\n【章法與結構】此段採用了先總後分的結構。首句「學者要收拾精神並歸一處」為總綱，點明學習必須專一。其後兩句分別從「修德」與「讀書」兩個方面舉例說明不專一的後果：「留意於事功名譽」導致「無實詣」，「寄興於吟詠風雅」導致「不深心」，正反對比，論證有力。\\\\n【思想與義理】這段話強調了「專一」在求學與修身過程中的重要性。作者認為，無論是品德的修養還是學問的探求，都忌諱心有旁騖。如果過度追求外在的功名或流於表面的風雅，就會失去內在的篤實與深刻。這體現了中國傳統文化中重視「誠敬」與「內求」的治學精神，警示世人切莫捨本逐末。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-59\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":59,\"canonicalText\":\"人人有個大慈悲，維摩屠劊無二心也；處處有種真趣味，金屋茅簷非兩地也。只是欲閉情封，當面錯過，便咫尺千里矣。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-59_s-1\",\"cai-gen-tan_ch-3_p-59_s-2\",\"cai-gen-tan_ch-3_p-59_s-3\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"每個人的內心都擁有著廣大的慈悲之心，即使是菩薩維摩詰與殺生屠夫，他們本質上的佛心也沒有什麼不同；每個地方都蘊含著真實的生活趣味，即使是富麗堂皇的金屋與簡陋破敗的茅舍，在獲得心靈愉悅上並不是截然不同的境界。只是因為人們被私慾所蒙蔽、被情感所封閉，往往當面錯過了這些美好，結果明明近在眼前，卻感覺像相隔千里一樣遙遠。\",\"analysis\":\"【訓詁與名物】「大慈悲」佛家語，指廣大無私的救世之心。「維摩」即維摩詰，大乘佛教中的在家菩薩，象徵覺悟者。「屠劊」指屠夫與劊子手，象徵造殺業者。「金屋」指富貴人家的華麗居所。「茅簷」指窮苦人家的簡陋茅草屋。「欲閉情封」指被私慾和世俗情感蒙蔽了本心。「咫尺千里」比喻距離雖近，但心理上的隔閡極大。\\\\n【章法與結構】前兩句使用平行的對偶句式，從「人心」與「處境」兩個維度，運用極端的對比（維摩與屠劊、金屋與茅簷）來破除世俗的二元對立。最後一句以「只是」作為轉折，點出凡夫俗子之所以無法體會這種平等境界的原因，在於被慾望蒙蔽，導致「咫尺千里」的遺憾。\\\\n【思想與義理】此段深受佛教禪宗「眾生皆有佛性」以及「平常心是道」思想的影響。作者認為，無論是聖人還是惡人，無論是富貴還是貧賤，其內在的本性與生活的真趣都是平等的。阻礙我們認識這點的，並非外在條件，而是內心的「欲閉情封」。只要打破執著，便能隨處發現真理與趣味。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-60\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":60,\"canonicalText\":\"進德修行，要個木石的念頭，若一有欣羨便趨欲境；濟世經邦，要段雲水的趣味，若一有貪著便墮危機。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-60_s-1\",\"cai-gen-tan_ch-3_p-60_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"增進品德與修養心性，必須要有一種像樹木石頭般不受外界誘惑的意志，如果心中一產生羨慕貪圖的念頭，就會立刻陷入物慾的泥沼之中；救濟社會與治理國家，必須要有一種像行雲流水般淡泊名利的胸懷，如果心中一產生貪婪眷戀的念頭，就會隨時墮入危險的深淵。\",\"analysis\":\"【訓詁與名物】「進德修行」指增進道德修養。「木石的念頭」比喻意志堅定，不為外界誘惑所動，如木石般無情無慾。「欣羨」指喜愛羨慕。「欲境」指充滿慾望的境界。「濟世經邦」指救濟世人、治理國家。「雲水的趣味」比喻如雲水般自由自在、淡泊名利的灑脫心態。「貪著」佛家語，指貪戀執著。\\\\n【章法與結構】這是一組工整的對偶句，分別探討「進德修行」（內聖）與「濟世經邦」（外王）兩個層面。前半句提出理想的心態（木石的念頭、雲水的趣味），後半句則警告一旦產生負面情緒（欣羨、貪著）所帶來的不良後果（趨欲境、墮危機）。兩相對照，警示意味濃厚。\\\\n【思想與義理】此文深刻探討了修身與治國的心理條件。作者認為，修身需要極強的定力，像木石一樣不被物慾所牽引；而治國則需要極高的境界，像雲水一樣不被權力所羈絆。這體現了「無欲則剛」與「功成身退」的道家智慧，警告世人，無論是追求個人完善還是建功立業，最大的敵人都是內心的貪念。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-61\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":61,\"canonicalText\":\"肝受病則目不能視，腎受病則耳不能聽。病受於人所不見，必發於人所共見。故君子欲無得罪於昭昭，先無得罪於冥冥。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-61_s-1\",\"cai-gen-tan_ch-3_p-61_s-2\",\"cai-gen-tan_ch-3_p-61_s-3\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"肝臟生了病，眼睛就會看不清楚；腎臟生了病，耳朵就會聽不見聲音。疾病往往潛伏在人們看不見的內部臟器，但最終必定會發作顯露在眾人都看得見的外部器官上。因此，君子如果不想在光天化日之下做出違背道德而被眾人指責的事，就必須先在暗處獨處時，不做出任何違背良心的事情。\",\"analysis\":\"【訓詁與名物】中醫理論認為「肝開竅於目，腎開竅於耳」，故肝病影響視力，腎病影響聽力。「昭昭」指光明天白之處，引申為眾目睽睽的公開場合。「冥冥」指昏暗不明之處，引申為無人知曉的私下場合。「得罪」此指違背道德理法而獲罪。\\\\n【章法與結構】此段運用了「由生理推及倫理」、「由自然推及人事」的類比論證手法。先以中醫學理的「病受於內，必發於外」作為鋪墊，接著以「故」字引出結論，將其引申到君子的修養工夫上，推導出「欲無得罪於昭昭，先無得罪於冥冥」的深刻哲理。\\\\n【思想與義理】這段話的核心在於闡述儒家「慎獨」的思想。作者借用醫學常識說明瞭一個道理：內在的隱微之處往往決定了外在的顯著表現。君子要想在公眾面前保持高尚的品德，就必須在無人監督的暗處嚴格要求自己，不可有絲毫的欺暗室之舉。這強調了道德修養必須表裡如一，從細微處下功夫。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-62\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":62,\"canonicalText\":\"福莫福於少事，禍莫禍於多心。惟省事者方知少事之為福；惟平心者始知多心之為禍。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-62_s-1\",\"cai-gen-tan_ch-3_p-62_s-2\",\"cai-gen-tan_ch-3_p-62_s-3\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"人生最大的福氣，沒有比得上無牽無掛、少惹事端了；人生最大的災禍，沒有比得上疑神疑鬼、心機太重了。只有那些善於減少繁雜事務的人，才能夠真正體會到少事清閒所帶來的福氣；只有那些心境平和恬淡的人，才能夠真正明白多疑多慮所帶來的災禍。\",\"analysis\":\"【訓詁與名物】「少事」指事情少，沒有繁雜事務的牽絆。「多心」指心思複雜，多疑多慮。「省事」指減少事務，不生事端。「平心」指心境平和，沒有雜念。\\\\n【章法與結構】此段採用了迴環往復的句式結構。前兩句提出核心論點：「福莫福於少事，禍莫禍於多心」，確立了「少事」為福、「多心」為禍的對立關係。後兩句則進一步深化，強調只有「省事者」和「平心者」才能真正具備這種覺悟，前後呼應，語意層層遞進。\\\\n【思想與義理】這段話充滿了老莊哲學中「清靜無為」與「少私寡慾」的智慧。世人往往以多財多權為福，作者卻認為真正的福氣在於「少事」帶來的清閒自在；世人往往認為災禍來自外界，作者卻指出最大的災禍源於內心的「多心」與焦慮。這提醒人們應該放下無謂的爭逐，保持內心的平靜，才是獲得幸福的根本途徑。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-63\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":63,\"canonicalText\":\"處治世宜方，處亂世當圓，處叔季之世當方圓並用。待善人宜寬，待惡人當嚴，待庸眾之人宜寬嚴互存。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-63_s-1\",\"cai-gen-tan_ch-3_p-63_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"身處政治清明、社會安定的治世，行事應當正直方正；身處政治黑暗、局勢動盪的亂世，處世應當圓融變通；身處道德衰微、將亂未亂的末世，應當方圓並用，靈活應對。對待善良的人應當寬容厚道，對待邪惡的人應當嚴厲防範，對待平庸的普通大眾，則應當寬嚴相濟、相輔相行。\",\"analysis\":\"【主題與背景】此段展現了儒家通達權變的處世智慧與因時、因人制宜的管理哲學。\\\\n【訓詁與名物】「治世」指政治清明、社會安定的時代；「方」指方正、剛直有原則；「圓」指圓融、機變通達；「叔季之世」指道德衰微、法度將壞未壞的末世；「庸眾」指平庸、缺乏主見的普通大眾。\\\\n【章法與結構】全段分為兩層，結構極為嚴密對稱。第一層論「處世」之道，按治世、亂世、叔季之世三種時代背景，提出方、圓、方圓並用的策略；第二層論「待人」之道，按善人、惡人、庸眾三種對象，提出寬、嚴、寬嚴互存的方法。\\\\n【思想與義理】「方」是做人的道德底線，「圓」是保全自己與成就事業的手段。在不同的時代背景與面對不同素質的人羣時，不能拘泥於單一的原則，而必須靈活運用寬嚴、方圓，這既避免了一味剛直而招禍，也避免了一味圓滑而喪失底線。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-64\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":64,\"canonicalText\":\"我有功於人不可念，而過則不可不念；人有恩於我不可忘，而怨則不可不忘。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-64_s-1\",\"cai-gen-tan_ch-3_p-64_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"我對別人有功勞，不可以常常掛在心上，但如果對別人有過錯，就絕對不可以不記在心裡；別人對我有恩惠，不可以輕易忘記，但如果別人對我有怨恨或得罪我的地方，就絕對不可以不忘記。\",\"analysis\":\"【訓詁與名物】「念」在此指掛念、惦記。「過」指過失、過錯。「恩」指恩惠、幫助。「怨」指仇恨、怨懟。\\\\n【章法與結構】本段採用極為工整的對仗與迴環句式。前半句以「我對人」的功與過作對比，指出「不可念功，不可不念過」；後半句以「人對我」的恩與怨作對比，指出「不可忘恩，不可不忘怨」。兩相輝映，構成一種嚴謹的道德思辨邏輯。\\\\n【思想與義理】這段話是《菜根譚》中關於人際交往與自我修養的經典格言。它教導人們在處理恩怨得失時，必須採取「嚴以律己，寬以待人」的態度。記住別人的恩惠與自己的過錯，能培養感恩與反省之心；忘記自己的功勞與別人的過錯，能避免驕傲與仇恨的糾纏。這是一種極具道家「不爭」與儒家「恕道」色彩的高超處世哲學。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-65\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":65,\"canonicalText\":\"心地乾凈，方可讀書學古。不然，見一善行，竊以濟私；聞一善言，假以覆短。是又藉寇兵而齎盜糧矣。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-65_s-1\",\"cai-gen-tan_ch-3_p-65_s-2\",\"cai-gen-tan_ch-3_p-65_s-3\",\"cai-gen-tan_ch-3_p-65_s-4\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"必須先保持內心清白乾淨，才可以去讀書、學習古人的智慧。否則，看到古人的一個善行，就會偷偷拿來當作謀取私利的工具；聽到一句至理名言，就會假借來掩飾自己的缺點。這就如同借武器給敵人、送糧食給強盜一樣，反受其害。\",\"analysis\":\"【主題與背景】此段深刻論述了「德」與「才」的關係，強調讀書治學的根本在於「立心」。\\\\n【訓詁與名物】「學古」指學習古人的聖賢智慧；「濟私」指滿足或謀求個人私利；「覆短」指掩飾自己的缺點與過失；「藉寇兵而齎盜糧」語出李斯《諫逐客書》，「藉」同借，「齎」為贈送，比喻助長敵人的勢力，反受其害。\\\\n【章法與結構】本段先提出「心地乾淨」是讀書的先決條件；接著以「不然」進行反面假設，列舉心術不正者讀書的兩種惡劣行徑（竊善行以濟私，假善言以覆短）；最後引用歷史典故作結，將這種行為定性為助紂為虐、自我毀滅。\\\\n【思想與義理】如果心術不正、動機不純，那麼學習再多的聖賢道理，非但不能提升道德修養，反而會將學問作為偽裝邪惡、謀取私利的工具。這種有才無德的人，對社會的危害甚至大於無才無德之人。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-66\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":66,\"canonicalText\":\"奢者富而不足，何如儉者貧而有餘。能者勞而俯怨，何如拙者逸而全真。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-66_s-1\",\"cai-gen-tan_ch-3_p-66_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"奢侈的人雖然富有，但總覺得不夠用；哪裡比得上節儉的人雖然貧窮，卻總是覺得有結餘呢。有能力的人因為過度操勞，反而容易招致別人的怨恨；哪裡比得上笨拙的人雖然安逸，卻能保全純真的本性呢。\",\"analysis\":\"【訓詁與名物】「奢者」指生活奢侈浪費的人。「儉者」指生活節儉的人。「俯怨」的「俯」通「府」，引申為招致、聚集，指招來怨恨。「拙者」指看似笨拙、不善機巧的人。「全真」指保全天然純真的本性。\\\\n【章法與結構】本段由兩個結構對稱的反問句組成。第一句探討財富與慾望的關係（富而不足對比貧而有餘）；第二句探討才能與境遇的關係（能而招怨對比拙而全真）。皆以「何如」（怎麼比得上）作為轉折，強烈表達了作者的價值取向。\\\\n【思想與義理】此段反映了《菜根譚》深受老莊思想影響的一面。作者批判了世俗對於「富貴」與「才能」的盲目追求。奢侈會放大慾望，使人永遠處於匱乏的焦慮中；而過度展現才能則容易招致嫉妒與勞累。反之，節儉能讓人知足常樂，「守拙」則能避免捲入是非，保全生命的真實與安寧。這是一種超越物質與功名、追求心靈自由的生命智慧。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-67\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":67,\"canonicalText\":\"讀書不見聖賢，如鉛槧傭。居官不愛子民，如衣冠盜。講學不尚躬行，如口頭禪。立業不思種德。如眼前花。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-67_s-1\",\"cai-gen-tan_ch-3_p-67_s-2\",\"cai-gen-tan_ch-3_p-67_s-3\",\"cai-gen-tan_ch-3_p-67_s-4\",\"cai-gen-tan_ch-3_p-67_s-5\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"讀書如果不能體悟並實踐聖賢的精神，就不過是個抄寫書本的工匠。做官如果不愛護體恤百姓，就不過是個穿著官服的強盜。講學做學問如果不注重身體力行，就不過是毫無實效的口頭禪。創業如果不考慮積德行善，就不過是轉瞬即逝的眼前曇花。\",\"analysis\":\"【主題與背景】此段以極具張力的比喻，痛斥了社會上知行脫節與缺乏道德責任感的四大弊病。\\\\n【訓詁與名物】「不見聖賢」指不能體悟聖賢的精神境界；「鉛槧傭」指古代用鉛粉和木簡從事機械抄寫的僱工；「衣冠盜」指穿著官服卻魚肉鄉民的強盜；「躬行」指親身實踐；「口頭禪」指空談而無實證的言論；「種德」指積累道德善行；「眼前花」指轉瞬即逝的虛幻事物。\\\\n【章法與結構】全段採用整齊的四言排比句式，每一句皆由「行為＋缺失＋比喻」構成（讀書不見聖賢如鉛槧傭等）。四組對比層層排比，氣勢磅礡，語言犀利，極具批判力道。\\\\n【思想與義理】作者強調，讀書必須有靈魂（見聖賢），做官必須有仁愛（愛子民），學問必須有實踐（尚躬行），事業必須有根基（思種德）。這深刻體現了王陽明「知行合一」的哲學理念與儒家經世致用的實幹精神。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-68\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":68,\"canonicalText\":\"人心有部真文章，都被殘編斷簡封固了；有部真鼓吹，都被妖歌艷舞湮沒了。學者須掃除外物直覓本來，纔有個真受用。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-68_s-1\",\"cai-gen-tan_ch-3_p-68_s-2\",\"cai-gen-tan_ch-3_p-68_s-3\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"每個人的內心其實都有一部反映真理的絕妙文章，卻常常被那些殘缺不全的古書典籍所封鎖禁錮了；每個人的內心也有一部演奏真情實感的天然樂章，卻往往被那些淫靡艷麗的歌舞所淹沒覆蓋了。因此，求學修道的人必須掃除外在物質的幹擾與迷惑，直接去探求自己本來的真性情，這樣才能獲得真正受用無窮的益處。\",\"analysis\":\"【訓詁與名物】：「真文章」與「真鼓吹」比喻人內心天然純真的本性與良知。「殘編斷簡」本指殘缺不全的古書竹簡，此處代指僵化教條的學術理論與文字障。「封固」指封鎖禁錮。「妖歌艷舞」指靡靡之音與聲色之好。「湮沒」意為埋沒、淹沒。「學者」指學習修道之人。「外物」指心外的一切物質誘惑與外在羈絆。「直覓本來」指直接探求內心本原的真性情。「真受用」指真正實在的益處與受用。\\\\n\\\\n【章法與結構】：全段先破後立。前兩句為「破」，運用對仗手法，「人心有部真文章，都被殘編斷簡封固了」與「有部真鼓吹，都被妖歌艷舞湮沒了」相互呼應，揭示了本心被外物蒙蔽的現狀；最後一句為「立」，「學者須掃除外物直覓本來，纔有個真受用」，點明瞭恢復本心的方法與結果。結構清晰，語勢連貫。\\\\n\\\\n【思想與義理】：此段蘊含著王陽明心學「心即理」與禪宗「明心見性」的思想。作者認為，真理與最美的樂章不在心外，而在每個人的本心之中。然而，世人往往被外在的教條（殘編斷簡）所束縛，或者被感官的享樂（妖歌艷舞）所迷惑，從而喪失了自我。真正的修行在於「掃除外物」，擺脫名相與物慾的幹擾，回歸內心的清淨與純真，如此方能獲得精神的自由與充實。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-69\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":69,\"canonicalText\":\"苦心中常得悅心之趣；得意時便生失意之悲。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-69_s-1\",\"cai-gen-tan_ch-3_p-69_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"在經歷困苦煎熬的過程中，往往能體會到讓心靈愉悅的奇妙樂趣；而在春風得意、驕傲自滿的時候，卻容易種下日後失意悲哀的禍根。\",\"analysis\":\"【訓詁與名物】：「苦心」指費盡心思、經歷艱苦磨難的心境。「悅心之趣」指發自內心深處的喜悅與情趣。「得意」指稱心如意、心滿意足。「失意」指不如意、遭遇挫折。「悲」指悲傷、哀痛。這幾組詞彙語義相對，言簡意賅地概括了人生中情感體驗的翻轉與變化。\\\\n\\\\n【章法與結構】：這是一句極其凝練的對偶句。「苦心中」對「得意時」，「常得」對「便生」，「悅心之趣」對「失意之悲」。前後兩半句各自構成了一個看似矛盾實則合理的因果關係，同時兩半句之間又形成了一種強烈的對比反差，極具張力，發人深省。\\\\n\\\\n【思想與義理】：這句話深刻揭示了老子「禍兮福之所倚，福兮禍之所伏」的辯證哲理。在困境與苦難中，人們因為不斷奮鬥與突破自我，往往能獲得更深層次的精神滿足與成長之樂；相反，在順境與得意之時，若放縱自己、失去警惕，便容易招致失敗，從而陷入悲痛之中。這警示人們要以平常心對待順逆，在逆境中不餒，在順境中不驕，保持心靈的清醒與平衡。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-70\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":70,\"canonicalText\":\"富貴名譽自道德來者，如山林中花，自是舒徐。繁衍自功業來者，如盆檻中花，便有遷徙廢興。若以權力得者，其根不植，其萎可立而待矣。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-70_s-1\",\"cai-gen-tan_ch-3_p-70_s-2\",\"cai-gen-tan_ch-3_p-70_s-3\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"如果一個人的財富、地位與名譽是憑藉高尚的道德修養得來的，那就如同生長在山林深處的野花一樣，自然能夠從容舒展、生機勃勃；如果是依靠建立功業所換來的，那就如同栽種在盆檻之中的花朵一般，會隨著環境的變遷而時興時衰；若是僅憑權勢與武力強行奪取的，那就像是沒有紮根的植物，它的枯萎敗落立刻就可以預見了。\",\"analysis\":\"【訓詁與名物】：「舒徐」指舒展從容、悠然自得。「繁衍」此處指事物發展壯大。「功業」指建立的功勳與事業。「盆檻」指種花的盆缽與欄杆。「遷徙廢興」指搬遷移動、衰落與興盛。「根不植」指沒有紮下根基。「立而待」指站在那裡就可以等到，形容時間極短、很快就會發生。\\\\n\\\\n【章法與結構】：全段採用了層層遞進的排比與博喻手法，將富貴名譽的來源分為三等：道德、功業、權力，並分別將其比喻為「山林中花」、「盆檻中花」與「其根不植」之花。通過這三個生動的比喻，將無形的精神境界具象化，條理清晰地論述了三種不同的人生追求及其必然的結果。\\\\n\\\\n【思想與義理】：此段體現了儒家崇尚道德、輕視權術的價值觀。作者將道德視為人生最根本、最持久的基石。因道德而來的榮譽是內在的、自然的，故能長久安泰；因功業而來的榮譽依賴於外在條件，故有興衰起伏；而靠權力巧取豪奪來的富貴則是無源之水、無本之木，必然迅速覆滅。這告誡世人，唯有修養德行，方是立身處世、保全福報的長久之計。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-71\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":71,\"canonicalText\":\"棲守道德者，寂寞一時；依阿權勢者，淒涼萬古。達人觀物外之物，思身後之身，寧受一時之寂寞，毋取萬古之淒涼。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-71_s-1\",\"cai-gen-tan_ch-3_p-71_s-2\",\"cai-gen-tan_ch-3_p-71_s-3\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"堅守道德規範而不願同流合污的人，或許會忍受一時的冷落與寂寞；而那些依附權貴、阿諛奉承的人，最終必將遭受萬古的唾罵與淒涼。通達事理的智者，能夠洞察物質之外的真理，考量身故之後的名聲，因此寧可承受眼前的短暫寂寞，也絕不換取永遠的悲涼下場。\",\"analysis\":\"【訓詁與名物】：「棲守」指堅守、安身於某種信仰或原則。「寂寞」此處指不受世俗重視、孤立無援。「依阿」即阿附，指迎合、依附權勢。「淒涼」指悲慘冷落。「萬古」指千秋萬代、永遠。「達人」指通達事理、心胸開闊的智者。「物外之物」指超越物質利益之上的精神追求與真理。「身後之身」指死後的名聲與評價。「毋取」即不要選取。\\\\n\\\\n【章法與結構】：本段在結構上採用了鮮明的對比與對稱。前半部分以「棲守道德者，寂寞一時」對照「依阿權勢者，淒涼萬古」，將短暫與永恆、道德與權勢進行對立；後半部分以「達人」的視角，從「觀物外之物，思身後之身」的宏觀維度出發，得出「寧受……毋取……」的結論，邏輯嚴密，氣勢磅礴。\\\\n\\\\n【思想與義理】：此段宣揚了儒家重義輕利、追求精神不朽的凜然氣節。在世俗中，堅守道德往往意味著失去眼前的利益與熱鬧，而趨炎附勢似乎能換來一時的顯赫。然而，作者指出，真正的智者應具備超越時空的眼光（物外之物、身後之身）。一時的寂寞換來的是靈魂的安寧與歷史的肯定，而依附權勢帶來的榮華終將如過眼雲煙，留下的是千古罵名。這是一種高潔的人生觀與價值抉擇。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-72\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":72,\"canonicalText\":\"春至時和，花尚鋪一段好色，鳥且囀幾句好音。士君子幸列頭角，復遇溫飽，不思立好言、行好事，雖是在世百年，恰似未生一日。\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-72_s-1\",\"cai-gen-tan_ch-3_p-72_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"當春天到來、氣候溫和的時候，花朵尚且知道綻放出一片絢爛的色彩，鳥兒尚且知道婉轉啼叫出幾聲動聽的旋律。身為讀書人的君子，有幸能夠在社會上嶄露頭角，又過著衣食無憂的溫飽生活，如果不想著著書立說發表好的言論、身體力行去做對社會有益的好事，那麼即使他在世上活了一百歲，也跟一天都沒活過沒有什麼兩樣。\",\"analysis\":\"【訓詁與名物】：「時和」指氣候溫和、時令適宜。「尚」與「且」皆有尚且之意。「鋪」指鋪展、呈現。「囀」指鳥兒婉轉地鳴叫。「士君子」指讀書人、有道德修養的人。「列頭角」即嶄露頭角，指在社會上有地位、有才華。「溫飽」指衣食無憂。「立好言」指立言，傳播有益的道理。「行好事」指立德、立功，做造福社會之事。\\\\n\\\\n【章法與結構】：全段採用了託物言志與對比的手法。開篇先以春日裡花開鳥鳴的自然美景起興，營造出生機勃勃的氛圍，並以此作為參照物；隨後筆鋒一轉，將自然界的草木禽鳥與作為萬物之靈的「士君子」進行對比。最後以「雖是……恰似……」的假設句式收尾，語氣嚴厲，具有強烈的警醒意味。\\\\n\\\\n【思想與義理】：這段話深刻體現了儒家「三不朽」（立德、立功、立言）的價值觀與強烈的社會責任感。作者認為，生命的價值不在於壽命的長短（在世百年），而在於能否為世間留下美好的貢獻。連無知的花鳥都能在美好的時節裝點自然，作為擁有才華和良好生活條件的君子，如果不去傳播真理（立好言）、造福大眾（行好事），那就是虛度光陰、辜負了生命。這是一種積極入世、奮發有為的人生態度。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"cai-gen-tan_ch-3_p-73\",\"chapterId\":\"cai-gen-tan_ch-3\",\"order\":73,\"canonicalText\":\"學者有段兢業的心思，又要有段瀟灑的趣味。若一味斂束清苦，是有秋殺無春生，何以發育萬物？\",\"sentenceIds\":[\"cai-gen-tan_ch-3_p-73_s-1\",\"cai-gen-tan_ch-3_p-73_s-2\"],\"sourceRefs\":[{\"label\":\"《菜根譚》—中國哲學書電子化計劃\",\"edition\":\"明萬曆本《菜根譚》校本\",\"location\":\"https://ctext.org/cai-gen-tan/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《菜根譚》—維基文庫\",\"edition\":\"三臺館本《菜根譚》\",\"location\":\"https://zh.wikisource.org/zh-hant/菜根譚\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"求學的人應該要有一種戰戰兢兢、勤勉謹慎的心志，同時也要有一種灑脫自在、不受拘束的生活情趣。如果一味地自我約束、過著清貧刻苦的生活，那就如同只有秋天的肅殺之氣而沒有春天的生機盎然，這樣怎麼能夠孕育和發展出世間萬物呢？\",\"analysis\":\"【訓詁與名物】「學者」指求學、修養學問的人。「兢業」即戰戰兢兢、勤謹從事之意。「瀟灑」指自然大方、不拘泥、有灑脫之風。「斂束」指收斂、約束。「清苦」指清貧刻苦。「秋殺」指秋氣肅殺，使萬物凋零。「春生」指春氣溫和，使萬物生長。\\\\n【章法與結構】前半段以「有段...又要段...」並列，點出修學的兩面；後半段以「若一味...是有...無...」作為反面論述，並以「何以...」的激問句作結。文字生動，充滿自然節氣與人事修養相呼應的韻律美。\\\\n【思想與義理】本文探討求學與修道之人的心靈調劑。作者認為，嚴謹的自律與治學態度是必須的，但若過度苛求自我，使生命失去活潑的生機與樂趣，便會落入枯槁死寂。正如大自然需要春風化雨才能生生不息，人也需要一份瀟灑與豁達，才能讓學問與生命相互融通，達到至善圓滿的境界。\",\"historicalContext\":\"\",\"keywords\":[]}}],\"sentences\":[{\"id\":\"cai-gen-tan_ch-3_p-1_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-1\",\"order\":1,\"canonicalText\":\"兩個空拳握古今，握住了還當放手；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-1_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-1\",\"order\":2,\"canonicalText\":\"一條竹杖挑風月，挑到時也要息肩。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-2_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-2\",\"order\":1,\"canonicalText\":\"堦下幾點飛翠落紅，收拾了無非詩料；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-2_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-2\",\"order\":2,\"canonicalText\":\"窻前一片浮青映白，悟入處盡是禪機。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-3_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-3\",\"order\":1,\"canonicalText\":\"忽覩天際彩雲，常疑好事皆虛事；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-3_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-3\",\"order\":2,\"canonicalText\":\"再觀山中閒木，方信閒人是福人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-4_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-4\",\"order\":1,\"canonicalText\":\"東海水曾聞無定波，世事何須扼腕？\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-4_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-4\",\"order\":2,\"canonicalText\":\"北邙山未曾留閒地，人生且自舒眉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-5_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-5\",\"order\":1,\"canonicalText\":\"天地尚無停息，日月且有盈虧，況區區人世能事事圓滿而時時暇逸乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-5_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-5\",\"order\":2,\"canonicalText\":\"只是向忙裏偷閒，遇缺處知足，則操縱在我，作息自如，即造物不得與之論勞逸較虧盈矣！\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-6_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-6\",\"order\":1,\"canonicalText\":\"「霜天聞鶴唳，雪夜聽雞鳴，」得乾坤清純之氣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-6_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-6\",\"order\":2,\"canonicalText\":\"「晴空看鳥飛，活水觀魚戲，」識宇宙活潑之機。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-7_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-7\",\"order\":1,\"canonicalText\":\"閒烹山茗聽瓶聲，爐內識陰陽之理；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-7_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-7\",\"order\":2,\"canonicalText\":\"漫履楸枰觀局戲，手中悟生殺之機。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-8_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-8\",\"order\":1,\"canonicalText\":\"芳菲園林看蜂忙，覷破幾般塵情世態；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-8_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-8\",\"order\":2,\"canonicalText\":\"寂寞衡茅觀燕寢，引起一種冷趣幽思。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-9_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-9\",\"order\":1,\"canonicalText\":\"會心不在遠，得趣不在多。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-9_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-9\",\"order\":2,\"canonicalText\":\"盆池拳石間，便居然有萬裏山川之勢，片言隻語內，便宛然見萬古聖賢之心，纔是高士得眼界，達人得胸襟。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-10_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-10\",\"order\":1,\"canonicalText\":\"心與竹俱空，問是非何處安腳？\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-10_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-10\",\"order\":2,\"canonicalText\":\"貌偕松共瘦，知憂喜無由上眉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-11_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-11\",\"order\":1,\"canonicalText\":\"趨炎雖暖，暖後更覺寒威；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-11_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-11\",\"order\":2,\"canonicalText\":\"食蔗能甘，甘餘便生苦趣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-11_s-3\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-11\",\"order\":3,\"canonicalText\":\"何似養志於清修而炎涼不涉，棲心於淡泊而甘苦俱忘，其自得為更多也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-12_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-12\",\"order\":1,\"canonicalText\":\"席擁飛花落絮，坐林中錦繡團裀；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-12_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-12\",\"order\":2,\"canonicalText\":\"爐烹白雪清冰，熬天上玲瓏液髓。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-13_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-13\",\"order\":1,\"canonicalText\":\"逸態閒情，惟期自尚，何事外修邊幅；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-13_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-13\",\"order\":2,\"canonicalText\":\"清標傲骨，不願人憐，無勞多買胭脂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-14_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-14\",\"order\":1,\"canonicalText\":\"天地景物，如山間之空翠，水上之漣漪，潭中之雲影，草際之煙光，月下之花容，風中之柳態。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-14_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-14\",\"order\":2,\"canonicalText\":\"若有若無，半真半幻，最足以悅人心目而豁人性靈。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-14_s-3\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-14\",\"order\":3,\"canonicalText\":\"真天地間一妙境也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-15_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-15\",\"order\":1,\"canonicalText\":\"「樂意相關禽對語，生香不斷樹交花」，此是無彼無此的真機。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-15_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-15\",\"order\":2,\"canonicalText\":\"「野色更無山隔斷，天光常與水相連」，此是徹上徹下的真境。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-15_s-3\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-15\",\"order\":3,\"canonicalText\":\"吾人時時以此景象注之心目，何患心思不活潑，氣象不寬平！\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-16_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-16\",\"order\":1,\"canonicalText\":\"鶴唳、雪月、霜天、想見屈大夫醒時之激烈；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-16_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-16\",\"order\":2,\"canonicalText\":\"鷗眠、春風、暖日，會知陶處士醉裏之風流。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-17_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-17\",\"order\":1,\"canonicalText\":\"黃鳥情多，常向夢中呼醉客；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-17_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-17\",\"order\":2,\"canonicalText\":\"白雲意懶，偏來僻處媚幽人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-18_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-18\",\"order\":1,\"canonicalText\":\"棲遲蓬戶，耳目雖拘而神情自曠；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-18_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-18\",\"order\":2,\"canonicalText\":\"納結山翁，儀文雖略而意念常真。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-19_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-19\",\"order\":1,\"canonicalText\":\"滿室清風滿幾月，坐中物物見天心；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-19_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-19\",\"order\":2,\"canonicalText\":\"一溪流水一山雲，行處時時觀妙道。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-20_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-20\",\"order\":1,\"canonicalText\":\"炮鳳烹龍，放箸時與齏鹽無異；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-20_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-20\",\"order\":2,\"canonicalText\":\"懸金佩玉，成灰處共瓦礫何殊。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-21_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-21\",\"order\":1,\"canonicalText\":\"「掃地白雲來」，纔著工夫便起障。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-21_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-21\",\"order\":2,\"canonicalText\":\"「鑿池明月入」，能空境界自生明。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-22_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-22\",\"order\":1,\"canonicalText\":\"造化喚作小兒，切莫受渠戲弄；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-22_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-22\",\"order\":2,\"canonicalText\":\"天地尤為大塊，須要任我爐錘。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-23_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-23\",\"order\":1,\"canonicalText\":\"想到白骨黃泉，壯士之肝腸自冷；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-23_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-23\",\"order\":2,\"canonicalText\":\"坐老清溪碧嶂，俗流之胸次亦閒。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-24_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-24\",\"order\":1,\"canonicalText\":\"夜眠八尺，日啖二升，何須百般計較；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-24_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-24\",\"order\":2,\"canonicalText\":\"書讀五車，才分八斗，未聞一日清閒。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-25_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-25\",\"order\":1,\"canonicalText\":\"君子之心事，天青日白，不可使人不知；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-25_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-25\",\"order\":2,\"canonicalText\":\"君子之才華，玉韞珠藏，不可使人易知。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-26_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-26\",\"order\":1,\"canonicalText\":\"耳中常聞逆耳之言，心中常有拂心之事，纔是進德修行的砥石。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-26_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-26\",\"order\":2,\"canonicalText\":\"若言言悅耳，事事快心，便把此生埋在鴆毒中矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-27_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-27\",\"order\":1,\"canonicalText\":\"疾風怒雨，禽鳥慼慼；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-27_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-27\",\"order\":2,\"canonicalText\":\"霽月光風，草木欣欣，可見天地不可一日無和氣，人心不可一日無喜神。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-28_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-28\",\"order\":1,\"canonicalText\":\"醲肥辛甘非真味，真味只是淡；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-28_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-28\",\"order\":2,\"canonicalText\":\"神奇卓異非至人，至人只是常。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-29_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-29\",\"order\":1,\"canonicalText\":\"夜深人靜獨坐觀心；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-29_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-29\",\"order\":2,\"canonicalText\":\"始知妄窮而真獨露，每於此中得大機趣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-29_s-3\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-29\",\"order\":3,\"canonicalText\":\"既覺真現而妄難逃，又於此中得大慚忸。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-30_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-30\",\"order\":1,\"canonicalText\":\"恩裏由來生害，故快意時須早回頭；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-30_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-30\",\"order\":2,\"canonicalText\":\"敗後或反成功，故拂心處切莫放手。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-31_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-31\",\"order\":1,\"canonicalText\":\"藜口莧腸者，多冰清玉潔；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-31_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-31\",\"order\":2,\"canonicalText\":\"袞衣玉食者，甘婢膝奴顏。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-31_s-3\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-31\",\"order\":3,\"canonicalText\":\"蓋志以淡泊明，而節從肥甘喪矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-32_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-32\",\"order\":1,\"canonicalText\":\"面前的田地要放得寬，使人無不平之嘆；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-32_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-32\",\"order\":2,\"canonicalText\":\"身後的惠澤要流得長，使人有不匱之思。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-33_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-33\",\"order\":1,\"canonicalText\":\"路徑窄處留一步，與人行；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-33_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-33\",\"order\":2,\"canonicalText\":\"滋味濃的減三分，讓人嗜。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-33_s-3\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-33\",\"order\":3,\"canonicalText\":\"此是涉世一極樂法。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-34_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-34\",\"order\":1,\"canonicalText\":\"作人無甚高遠的事業，擺脫得俗情便入名流；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-34_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-34\",\"order\":2,\"canonicalText\":\"為學無甚增益的工夫，減除得物累便臻聖境。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-35_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-35\",\"order\":1,\"canonicalText\":\"寵利毋居人前，德業毋落人後，受享毋踰分外，修持毋減分中。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-36_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-36\",\"order\":1,\"canonicalText\":\"處世讓一步為高，退步即進步的張本；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-36_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-36\",\"order\":2,\"canonicalText\":\"待人寬一分是福，利人實利己的根基。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-37_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-37\",\"order\":1,\"canonicalText\":\"蓋世的功勞，當不得一個矜字；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-37_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-37\",\"order\":2,\"canonicalText\":\"彌天的罪過，當不得一個悔字。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-38_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-38\",\"order\":1,\"canonicalText\":\"完名美節，不宜獨任，分些與人，可以遠害全身；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-38_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-38\",\"order\":2,\"canonicalText\":\"辱行污名，不宜全推，引些歸己，可以韜光養德。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-39_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-39\",\"order\":1,\"canonicalText\":\"事事要留個有餘不盡的意思，便造物不能忌我，鬼神不能損我。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-39_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-39\",\"order\":2,\"canonicalText\":\"若業必求滿，功必求盈者，不生內變，必招外憂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-40_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-40\",\"order\":1,\"canonicalText\":\"家庭有個真佛，日用有種真道，人能誠心和氣、愉色婉言，使父母兄弟間形體兩釋、意氣交流，勝於調息觀心萬倍矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-41_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-41\",\"order\":1,\"canonicalText\":\"攻人之惡毋太嚴，要思其堪受；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-41_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-41\",\"order\":2,\"canonicalText\":\"教人以善毋過高，當使其可從。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-42_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-42\",\"order\":1,\"canonicalText\":\"糞蟲至穢變為蟬，而飲露於秋風；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-42_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-42\",\"order\":2,\"canonicalText\":\"腐草無光化為螢，而耀採於夏月。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-42_s-3\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-42\",\"order\":3,\"canonicalText\":\"故知潔常自污出，明每從暗生也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-43_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-43\",\"order\":1,\"canonicalText\":\"矜高倨傲，無非客氣降伏得，客氣下而後正氣伸；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-43_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-43\",\"order\":2,\"canonicalText\":\"情慾意識，盡屬妄心消殺得，妄心盡而後真心現。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-44_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-44\",\"order\":1,\"canonicalText\":\"飽後思味，則濃淡之境都消；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-44_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-44\",\"order\":2,\"canonicalText\":\"色後思媱，則男女之見盡絕。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-44_s-3\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-44\",\"order\":3,\"canonicalText\":\"故人當以事後之悔，悟破臨事之癡迷，則性定而動無不正。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-45_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-45\",\"order\":1,\"canonicalText\":\"居軒冕之中，不可無山林的氣味；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-45_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-45\",\"order\":2,\"canonicalText\":\"處林泉之下，須要懷廊廟的經綸。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-45_s-3\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-45\",\"order\":3,\"canonicalText\":\"處世不必徼功，無過便是功；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-45_s-4\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-45\",\"order\":4,\"canonicalText\":\"與人不要感德，無怨便是德。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-46_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-46\",\"order\":1,\"canonicalText\":\"憂勤是美德，太苦則無以適性怡情；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-46_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-46\",\"order\":2,\"canonicalText\":\"淡泊是高風，太枯則無以濟人利物。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-47_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-47\",\"order\":1,\"canonicalText\":\"事窮勢蹙之人，當原其初心；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-47_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-47\",\"order\":2,\"canonicalText\":\"功成行滿之士，要觀其末路。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-48_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-48\",\"order\":1,\"canonicalText\":\"富貴家宜寬厚而反忌剋，是富貴而貧賤，其行如何能享？\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-48_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-48\",\"order\":2,\"canonicalText\":\"聰明人宜斂藏而反炫耀，是聰明而愚懵，其病如何不敗！\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-49_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-49\",\"order\":1,\"canonicalText\":\"人情反覆，世路崎嶇。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-49_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-49\",\"order\":2,\"canonicalText\":\"行不去，須知退一步之法；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-49_s-3\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-49\",\"order\":3,\"canonicalText\":\"行得去，務加讓三分之功。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-50_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-50\",\"order\":1,\"canonicalText\":\"待小人不難於嚴，而難於不惡；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-50_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-50\",\"order\":2,\"canonicalText\":\"待君子不難於恭，而難於有禮。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-51_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-51\",\"order\":1,\"canonicalText\":\"寧守渾噩而黜聰明，留些正氣還天地；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-51_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-51\",\"order\":2,\"canonicalText\":\"寧謝紛華而甘淡泊，遺個清名在乾坤。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-52_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-52\",\"order\":1,\"canonicalText\":\"降魔者先降其心，心伏則羣魔退聽；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-52_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-52\",\"order\":2,\"canonicalText\":\"馭橫者先馭其氣，氣平則外橫不侵。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-53_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-53\",\"order\":1,\"canonicalText\":\"養弟子如養閨女，最要嚴出入，謹交遊。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-53_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-53\",\"order\":2,\"canonicalText\":\"若一接近匪人，是清凈田中下一不凈的種子，便終身難植嘉苗矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-54_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-54\",\"order\":1,\"canonicalText\":\"欲路上事，毋樂其便而姑為染指，一染指便深入萬仞；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-54_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-54\",\"order\":2,\"canonicalText\":\"理路上事，毋憚其難而稍為退步，一退步便遠隔千山。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-55_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-55\",\"order\":1,\"canonicalText\":\"念頭濃者自待厚，待人亦厚，處處皆厚；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-55_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-55\",\"order\":2,\"canonicalText\":\"念頭淡者自待薄，待人亦薄，事事皆薄。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-55_s-3\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-55\",\"order\":3,\"canonicalText\":\"故君子居常嗜好，不可太濃艷，亦不宜太枯寂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-56_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-56\",\"order\":1,\"canonicalText\":\"彼富我仁，彼爵我義，君子故不為君相所牢籠；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-56_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-56\",\"order\":2,\"canonicalText\":\"人定勝天，志壹動氣，君子亦不受造化之陶鑄。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-57_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-57\",\"order\":1,\"canonicalText\":\"立身不高一步立，如塵裏振衣、泥中濯足，如何超達？\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-57_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-57\",\"order\":2,\"canonicalText\":\"處世不退一步處，如飛蛾投燭、羝羊觸藩，如何安樂？\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-58_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-58\",\"order\":1,\"canonicalText\":\"學者要收拾精神並歸一處。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-58_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-58\",\"order\":2,\"canonicalText\":\"如修德而留意於事功名譽，必無實詣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-58_s-3\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-58\",\"order\":3,\"canonicalText\":\"讀書而寄興於吟詠風雅，定不深心。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-59_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-59\",\"order\":1,\"canonicalText\":\"人人有個大慈悲，維摩屠劊無二心也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-59_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-59\",\"order\":2,\"canonicalText\":\"處處有種真趣味，金屋茅簷非兩地也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-59_s-3\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-59\",\"order\":3,\"canonicalText\":\"只是欲閉情封，當面錯過，便咫尺千里矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-60_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-60\",\"order\":1,\"canonicalText\":\"進德修行，要個木石的念頭，若一有欣羨便趨欲境；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-60_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-60\",\"order\":2,\"canonicalText\":\"濟世經邦，要段雲水的趣味，若一有貪著便墮危機。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-61_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-61\",\"order\":1,\"canonicalText\":\"肝受病則目不能視，腎受病則耳不能聽。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-61_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-61\",\"order\":2,\"canonicalText\":\"病受於人所不見，必發於人所共見。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-61_s-3\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-61\",\"order\":3,\"canonicalText\":\"故君子欲無得罪於昭昭，先無得罪於冥冥。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-62_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-62\",\"order\":1,\"canonicalText\":\"福莫福於少事，禍莫禍於多心。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-62_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-62\",\"order\":2,\"canonicalText\":\"惟省事者方知少事之為福；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-62_s-3\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-62\",\"order\":3,\"canonicalText\":\"惟平心者始知多心之為禍。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-63_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-63\",\"order\":1,\"canonicalText\":\"處治世宜方，處亂世當圓，處叔季之世當方圓並用。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-63_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-63\",\"order\":2,\"canonicalText\":\"待善人宜寬，待惡人當嚴，待庸眾之人宜寬嚴互存。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-64_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-64\",\"order\":1,\"canonicalText\":\"我有功於人不可念，而過則不可不念；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-64_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-64\",\"order\":2,\"canonicalText\":\"人有恩於我不可忘，而怨則不可不忘。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-65_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-65\",\"order\":1,\"canonicalText\":\"心地乾凈，方可讀書學古。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-65_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-65\",\"order\":2,\"canonicalText\":\"不然，見一善行，竊以濟私；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-65_s-3\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-65\",\"order\":3,\"canonicalText\":\"聞一善言，假以覆短。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-65_s-4\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-65\",\"order\":4,\"canonicalText\":\"是又藉寇兵而齎盜糧矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-66_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-66\",\"order\":1,\"canonicalText\":\"奢者富而不足，何如儉者貧而有餘。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-66_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-66\",\"order\":2,\"canonicalText\":\"能者勞而俯怨，何如拙者逸而全真。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-67_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-67\",\"order\":1,\"canonicalText\":\"讀書不見聖賢，如鉛槧傭。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-67_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-67\",\"order\":2,\"canonicalText\":\"居官不愛子民，如衣冠盜。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-67_s-3\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-67\",\"order\":3,\"canonicalText\":\"講學不尚躬行，如口頭禪。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-67_s-4\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-67\",\"order\":4,\"canonicalText\":\"立業不思種德。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-67_s-5\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-67\",\"order\":5,\"canonicalText\":\"如眼前花。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-68_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-68\",\"order\":1,\"canonicalText\":\"人心有部真文章，都被殘編斷簡封固了；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-68_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-68\",\"order\":2,\"canonicalText\":\"有部真鼓吹，都被妖歌艷舞湮沒了。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-68_s-3\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-68\",\"order\":3,\"canonicalText\":\"學者須掃除外物直覓本來，纔有個真受用。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-69_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-69\",\"order\":1,\"canonicalText\":\"苦心中常得悅心之趣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-69_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-69\",\"order\":2,\"canonicalText\":\"得意時便生失意之悲。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-70_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-70\",\"order\":1,\"canonicalText\":\"富貴名譽自道德來者，如山林中花，自是舒徐。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-70_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-70\",\"order\":2,\"canonicalText\":\"繁衍自功業來者，如盆檻中花，便有遷徙廢興。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-70_s-3\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-70\",\"order\":3,\"canonicalText\":\"若以權力得者，其根不植，其萎可立而待矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-71_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-71\",\"order\":1,\"canonicalText\":\"棲守道德者，寂寞一時；\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-71_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-71\",\"order\":2,\"canonicalText\":\"依阿權勢者，淒涼萬古。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-71_s-3\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-71\",\"order\":3,\"canonicalText\":\"達人觀物外之物，思身後之身，寧受一時之寂寞，毋取萬古之淒涼。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-72_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-72\",\"order\":1,\"canonicalText\":\"春至時和，花尚鋪一段好色，鳥且囀幾句好音。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-72_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-72\",\"order\":2,\"canonicalText\":\"士君子幸列頭角，復遇溫飽，不思立好言、行好事，雖是在世百年，恰似未生一日。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-73_s-1\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-73\",\"order\":1,\"canonicalText\":\"學者有段兢業的心思，又要有段瀟灑的趣味。\",\"chunks\":[],\"tags\":[]},{\"id\":\"cai-gen-tan_ch-3_p-73_s-2\",\"workId\":\"cai-gen-tan\",\"chapterId\":\"cai-gen-tan_ch-3\",\"passageId\":\"cai-gen-tan_ch-3_p-73\",\"order\":2,\"canonicalText\":\"若一味斂束清苦，是有秋殺無春生，何以發育萬物？\",\"chunks\":[],\"tags\":[]}]}") as ChapterBundle
